    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'VEG-001'), '{"variant_label":"œuf mollet","rationale":"Un œuf mollet par assiette complète les lentilles en protéines sans alourdir le plat : le blanc pris et le jaune coulant se mêlent à la vinaigrette et lient le tout. Il se cuit à part pendant que les lentilles terminent leur cuisson.","operations":[{"op":"add","form":"Œuf cru","quantity":4,"unit":"u","role":"protéine"}],"steps":[{"op":"insert","after":3,"instruction":"Porter à ébullition une casserole d''eau et y plonger les œufs délicatement pendant quatre minutes exactement. Les plonger aussitôt dans un bain d''eau froide et les écaler dès qu''ils ont tiédi : le blanc doit être juste pris et le jaune encore coulant."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
