     'assaisonnement', false, 9);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 10);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Éplucher la patate douce et les carottes, les couper en morceaux de deux centimètres, et la courgette en demi-rondelles épaisses en gardant sa peau. Les tailles diffèrent volontairement : la courgette cuit deux fois plus vite que la racine, et des morceaux plus gros compensent en partie cet écart.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer l''huile dans une cocotte à feu moyen et y faire fondre l''oignon émincé cinq minutes, sans le colorer. Ajouter l''ail haché et le curry en poudre et remuer TRENTE SECONDES dans l''huile chaude avant tout liquide : c''est le geste qui décide du parfum, les arômes du curry étant solubles dans le gras et non dans l''eau. Une poudre jetée dans la sauce reste poudreuse et rêche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter les carottes et la patate douce, remuer pour les enrober du mélange épicé, puis verser le lait de coco. Saler et porter à frémissement. Le liquide ne couvre pas les légumes et c''est normal : ils vont rendre de l''eau et le niveau montera.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Couvrir et laisser mijoter vingt minutes à feu doux, en remuant deux ou trois fois pour que le fond n''attache pas — le lait de coco brûle vite. Les racines doivent alors être presque tendres, une lame entrant avec une légère résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter la courgette et poursuivre quinze minutes à découvert. Le découvert de cette seconde phase fait deux choses : il laisse la courgette cuire sans se déliter et il réduit la sauce, qui doit napper et non baigner.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Goûter et rectifier le sel plus généreusement qu''on ne le ferait d''habitude : la recette est écrite au curry en poudre là où les sources emploient une pâte, qui est salée. Poivrer et laisser reposer cinq minutes hors du feu avant de servir — la sauce épaissit encore en tiédissant.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-032', 'recipe_family', 'Curry de légumes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-032', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux pommes de terre plutôt qu''à la patate douce, avec petits pois surgelés et noix de cajou (750g)','Aux coings, à la cardamome, à la cannelle et au curcuma (chefsimon)','Au concentré de tomate, au cumin, au piment et au citron vert, en version relevée (marmiton)','Mouillé au bouillon de légumes et lié d''un yaourt plutôt qu''au lait de coco (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-032","variants":["Aux pommes de terre plutôt qu''à la patate douce, avec petits pois surgelés et noix de cajou (750g)","Aux coings, à la cardamome, à la cannelle et au curcuma (chefsimon)","Au concentré de tomate, au cumin, au piment et au citron vert, en version relevée (marmiton)","Mouillé au bouillon de légumes et lié d''un yaourt plutôt qu''au lait de coco (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-032', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('214269b3205326ee99362fcda30f007c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":2,"pungency":2,"richness":4,"freshness":1,"intensity":4},"dominant_flavors":["curry","lait de coco","patate douce","carotte"],"aroma_families":["épices chaudes","coco","végétal cuit","allium doux"],"target_textures":["légumes fondants en dés","sauce nappante"],"signature_ingredients":["Lait de coco","Curry en poudre","Patate douce crue, épluchée"],"identity_guardrails":["Le curry cuit trente secondes dans l''huile chaude avant tout liquide, sinon il reste poudreux","Racines d''abord, courgette ensuite : cuites ensemble, l''une est crue quand l''autre est en purée","La sauce nappe et ne baigne pas — la seconde moitié de la cuisson se fait à découvert","Aucune viande ni bouillon de viande : c''est un curry de légumes"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Moussaka végétarienne', 'moussaka vegetarienne', 'Grèce', 'Grèce',
     'meal', 'moussaka de légumes gratinée', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Moussaka végétarienne', 'Aubergines, courgettes et poivrons en couches sous une béchamel gratinée', ds.id, 'VAR-015',
    'Myko', 'editorial', 6, 45, 40, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '4895222327e13392879f5576177f0e8b',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['aubergine rôtie','béchamel','tomate mijotée','fromage gratiné']::text[],
    ARRAY['végétal grillé','lacté','tomate_cuite','origan']::text[], ARRAY['légumes fondants','croûte gratinée','sauce_épaisse']::text[],
    ARRAY['Aubergine fraîche','Emmental râpé','Lait entier']::text[], ARRAY['Les aubergines se dégorgent et se rôtissent au four : à la poêle elles boivent trois fois plus d''huile','La sauce aux légumes doit être franchement réduite — sans viande, rien n''absorbe l''eau et le gratin rend du jus','La béchamel se fait épaisse : c''est la seule chose qui tienne les couches d''un plat sans viande','Vingt minutes de repos avant de servir, sinon la part s''affaisse dans l''assiette']::text[],
    ARRAY['dégorgement','rôtissage','réduction','béchamel','montage','gratinage','repos']::text[], ARRAY['À la feta : 800 g émiettés entre les couches et 500 g de yaourt grec dans la béchamel, mozzarella pour gratiner (marmiton)','Mozzarella et parmesan à la place de l''emmental, 125 g et 100 g pour quatre (marmiton)','Aux haricots rouges : 200 g égouttés dans la sauce, avec persil et menthe fraîche, chapelure sur le dessus (750g)','Montée entre des feuilles de lasagne, avec olives vertes, câpres et piment d''Espelette (marmiton)']::text[], ARRAY['lait','gluten']::text[],
    'Se garde 4 jours au réfrigérateur, couvert, et se réchauffe par parts 15 minutes à 180 °C. Comme le pastitsio, il se coupe mieux froid. Se congèle 3 mois, cuit et refroidi, découpé en parts individuelles filmées séparément ; réchauffage direct au four, 30 minutes à 180 °C sous aluminium. Les légumes rôtis et la sauce se préparent 3 jours à l''avance et se gardent séparément, ce qui ramène le montage à dix minutes.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'GR-001'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

