  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Émincer les oignons et les faire fondre quinze minutes dans l''huile d''olive au fond d''une grande marmite, avec l''ail haché et le curcuma. Quatre cents grammes d''oignon pour six ne sont pas un aromate d''appoint : sans viande, c''est cette masse fondue qui donnera du corps au bouillon, et il faut la laisser aller jusqu''au blond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ajouter les tomates concassées et laisser réduire dix minutes, puis verser le bouillon de légumes, saler et poivrer, et porter à frémissement. Le bouillon doit être franchement assaisonné dès maintenant : la semoule qu''il arrosera est fade par nature et n''a rien pour se rattraper ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter les carottes et les navets en gros morceaux et cuire vingt-cinq minutes à couvert, puis les courgettes en tronçons et le poivron en lanières et cuire quinze minutes de plus. Les racines et les cucurbitacées n''ont pas le même temps : mises ensemble, on obtient soit des navets crus, soit des courgettes en bouillie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter les pois chiches égouttés dans les dix dernières minutes, le temps qu''ils se réchauffent et prennent le goût du bouillon. Cuits depuis le début, ils se défont et troublent le liquide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Pendant ce temps, verser la semoule dans un grand plat creux, l''arroser d''un volume égal de bouillon prélevé à la louche, couvrir et laisser gonfler dix minutes. Le bouillon plutôt que l''eau, c''est ce qui distingue une semoule de couscous d''une semoule nature — et c''est la seule occasion de la parfumer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Égrener la semoule à la main ou à la fourchette en y incorporant le beurre en parcelles, jusqu''à ce qu''elle soit lisse et sans grumeaux. Ce travail se fait pendant qu''elle est chaude : refroidie, elle se prend en blocs que rien ne défait. Le beurre enrobe chaque grain et les empêche de se ressouder.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Dresser la semoule en couronne, disposer les légumes égouttés au centre et servir le bouillon à part, en saucière. Le bouillon versé sur la semoule en cuisine la noie : chacun l''ajoute à son assiette, et c''est aussi ce qui permet de garder la semoule sèche pour le lendemain.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-025', 'recipe_family', 'Couscous végétarien',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-025', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux raisins secs, de 50 à 250 g gonflés dans le bouillon, avec un bâton de cannelle (chefsimon, 750g)','Aux haricots verts et petits pois : 500 g et 300 g ajoutés avec les courgettes, plus un fenouil et deux pommes de terre (marmiton)','Au ras el-hanout ou aux épices à couscous, deux pincées à une cuillerée à soupe, formes absentes ou bloquées au catalogue (chefsimon, 750g)','Aux champignons : deux boîtes émincées ajoutées au bouillon (chefsimon)','Version sautée : champignons, carottes et céleri au gingembre râpé et à la sauce soja, servis sur semoule sans bouillon (marmiton)','Au gingembre moulu, une demi-cuillerée à café avec le curcuma (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-025","variants":["Aux raisins secs, de 50 à 250 g gonflés dans le bouillon, avec un bâton de cannelle (chefsimon, 750g)","Aux haricots verts et petits pois : 500 g et 300 g ajoutés avec les courgettes, plus un fenouil et deux pommes de terre (marmiton)","Au ras el-hanout ou aux épices à couscous, deux pincées à une cuillerée à soupe, formes absentes ou bloquées au catalogue (chefsimon, 750g)","Aux champignons : deux boîtes émincées ajoutées au bouillon (chefsimon)","Version sautée : champignons, carottes et céleri au gingembre râpé et à la sauce soja, servis sur semoule sans bouillon (marmiton)","Au gingembre moulu, une demi-cuillerée à café avec le curcuma (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-025', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('fd36f68db33e2cfbbdb89eccf1ea885d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":2,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["curcuma","légumes du bouillon","oignon fondu","beurre"],"aroma_families":["épices chaudes","végétal cuit","oignon_compoté","beurre"],"target_textures":["semoule égrenée","légumes fondants","bouillon_clair"],"signature_ingredients":["Semoule de blé dur moyenne sèche","Pois chiche cuit, égoutté","Navet cru"],"identity_guardrails":["La semoule gonfle dans le bouillon et non dans l''eau : c''est sa seule occasion d''être parfumée","Les pois chiches sont ici la protéine du plat, pas une garniture — 250 g pour six, ajoutés en fin de cuisson","Racines d''abord, courgettes ensuite : ensemble, l''un est cru quand l''autre est en bouillie","Le bouillon se sert à part : versé sur la semoule en cuisine, il la noie et interdit tout reste"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
