  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Chili sin carne', 'chili sin carne', 'Tex-Mex, adapté en cuisine domestique française', 'Tex-Mex, adapté en cuisine domestique française',
     'meal', 'légumineuses', 'named_traditional_dish', 'spicy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Chili sin carne', 'Haricots rouges mijotés à la tomate avec poivrons et carottes, sans viande', ds.id, 'VAR-042',
    'Myko', 'editorial', 6, 20, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', 'e48bde7984d62da72b0c6f65ad765626',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":3,"pungency":4,"richness":2,"freshness":2,"intensity":4}'::jsonb, ARRAY['cumin','paprika fumé','tomate mijotée','haricot rouge']::text[],
    ARRAY['cumin','fumé','tomate_cuite','piment']::text[], ARRAY['sauce_épaisse','haricots fondants mais entiers','légumes fondants']::text[],
    ARRAY['Haricot rouge cuit, égoutté','Cumin moulu','Paprika fumé']::text[], ARRAY['Les épices s''ouvrent dans l''huile avant la tomate, sinon le plat garde un goût poudreux','On écrase une louche de haricots pour lier : c''est ce qui remplace la viande et évite toute farine','Le sel n''entre qu''après la cuisson des haricots, qu''il durcirait','Ni soja texturé ni haché végétal ici : trois pages sur six s''en passent entièrement, et le plat tient sur la légumineuse']::text[],
    ARRAY['suer','épices ouvertes dans le gras','mijotage','liaison par écrasement','repos']::text[], ARRAY['Aux protéines de soja texturées, 60 à 150 g réhydratées, ou à un haché végétal — formes absentes du catalogue (marmiton, chefsimon, 750g)','Au maïs doux, 140 g égouttés ajoutés avec les haricots (chefsimon, 750g)','Aux haricots noirs, 180 g crus en plus des rouges, avec du céleri et des champignons (chefsimon)','Servi avec un avocat en dés, un quart de citron jaune et une demi-échalote crue (chefsimon)','Relevé au tabasco, une demi à une cuillerée à café, ou au piment d''Espelette (marmiton, chefsimon, 750g)','Aux lentilles vertes : 350 g cuites avec les haricots (750g)']::text[], ARRAY[]::text[],
    'Se garde 5 jours au réfrigérateur et gagne beaucoup au deuxième jour, les épices ayant fini de se répartir. Se congèle 3 mois sans rien perdre : c''est l''un des meilleurs candidats du corpus au travail d''avance, et doubler les quantités ne coûte presque rien. Réchauffer à couvert et à feu doux avec deux cuillerées d''eau. Les restes servent aussi de garniture — sur une pomme de terre au four, dans une tortilla, sous un œuf au plat.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'MX-001'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
