  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler l''oignon, le poivron et la carotte en dés d''un demi-centimètre et les faire revenir douze minutes dans l''huile d''olive à feu moyen, jusqu''à ce que l''oignon soit translucide et la carotte encore ferme. Sans viande pour donner du corps, cette base est le seul fondement du plat : bâclée, le chili reste une soupe de haricots à la tomate.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ajouter l''ail haché, le cumin, le paprika fumé, l''origan et le cayenne, et remuer trente à quarante secondes dans le gras chaud avant tout liquide. Les épices moulues sont solubles dans la matière grasse et non dans l''eau : versées après la tomate, elles restent en suspension et donnent un goût poudreux au lieu d''un fond aromatique.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser les tomates concassées et le bouillon, porter à frémissement et laisser mijoter à découvert vingt-cinq minutes. Le sel n''entre pas encore : les haricots, même déjà cuits, se raffermissent dans un liquide salé et refusent ensuite de s''attendrir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter les haricots rouges rincés et égouttés et poursuivre vingt minutes à petits bouillons, en écrasant une louche de haricots contre la paroi de la cocotte. Cet écrasement partiel libère leur amidon et lie la sauce : c''est ce qui remplace la viande hachée dans le rôle d''épaississant, et c''est pourquoi un chili sin carne n''a pas besoin de farine.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Saler, poivrer, goûter et rectifier le piquant. Le chili doit être goûté à ce moment-là et non plus tôt : les épices ont eu quarante-cinq minutes pour se développer, et ce qui paraissait fort au départ s''est arrondi.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couper le feu, parsemer de coriandre ciselée et laisser reposer un quart d''heure à couvert avant de servir avec du riz. Ce repos n''est pas une politesse : la sauce s''épaissit encore en refroidissant légèrement, et le plat passe d''un état soupe à un état ragoût.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-042', 'recipe_family', 'Chili sin carne',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-042', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux protéines de soja texturées, 60 à 150 g réhydratées, ou à un haché végétal — formes absentes du catalogue (marmiton, chefsimon, 750g)','Au maïs doux, 140 g égouttés ajoutés avec les haricots (chefsimon, 750g)','Aux haricots noirs, 180 g crus en plus des rouges, avec du céleri et des champignons (chefsimon)','Servi avec un avocat en dés, un quart de citron jaune et une demi-échalote crue (chefsimon)','Relevé au tabasco, une demi à une cuillerée à café, ou au piment d''Espelette (marmiton, chefsimon, 750g)','Aux lentilles vertes : 350 g cuites avec les haricots (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-042","variants":["Aux protéines de soja texturées, 60 à 150 g réhydratées, ou à un haché végétal — formes absentes du catalogue (marmiton, chefsimon, 750g)","Au maïs doux, 140 g égouttés ajoutés avec les haricots (chefsimon, 750g)","Aux haricots noirs, 180 g crus en plus des rouges, avec du céleri et des champignons (chefsimon)","Servi avec un avocat en dés, un quart de citron jaune et une demi-échalote crue (chefsimon)","Relevé au tabasco, une demi à une cuillerée à café, ou au piment d''Espelette (marmiton, chefsimon, 750g)","Aux lentilles vertes : 350 g cuites avec les haricots (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-042', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e48bde7984d62da72b0c6f65ad765626'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":3,"pungency":4,"richness":2,"freshness":2,"intensity":4},"dominant_flavors":["cumin","paprika fumé","tomate mijotée","haricot rouge"],"aroma_families":["cumin","fumé","tomate_cuite","piment"],"target_textures":["sauce_épaisse","haricots fondants mais entiers","légumes fondants"],"signature_ingredients":["Haricot rouge cuit, égoutté","Cumin moulu","Paprika fumé"],"identity_guardrails":["Les épices s''ouvrent dans l''huile avant la tomate, sinon le plat garde un goût poudreux","On écrase une louche de haricots pour lier : c''est ce qui remplace la viande et évite toute farine","Le sel n''entre qu''après la cuisson des haricots, qu''il durcirait","Ni soja texturé ni haché végétal ici : trois pages sur six s''en passent entièrement, et le plat tient sur la légumineuse"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Lasagnes végétariennes', 'lasagnes vegetariennes', 'Italie', 'Italie',
     'meal', 'pâtes au four', 'named_traditional_dish', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Lasagnes végétariennes', 'Feuilles de lasagne alternées avec courgettes, aubergines et tomate, gratinées à la mozzarella', ds.id, 'VAR-043',
    'Myko', 'editorial', 6, 30, 35, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '02ad78a013909da281eeff81836c92cf',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['aubergine rôtie','tomate mijotée','mozzarella fondue','basilic']::text[],
    ARRAY['tomate_cuite','végétal grillé','lacté','basilic']::text[], ARRAY['croûte gratinée','pâtes_fermes','légumes fondants']::text[],
    ARRAY['Feuille de lasagne sèche','Aubergine fraîche','Mozzarella']::text[], ARRAY['Les légumes se rôtissent avant : crus entre les feuilles, ils rendent près d''un litre d''eau','La sauce tomate doit être franchement réduite — sans viande, rien n''absorbe l''excès','Aucune feuille ne doit rester sèche : partout où elle n''est pas mouillée, elle reste dure','Quinze minutes de repos avant la découpe, faute de quoi la part coule dans l''assiette']::text[],
    ARRAY['rôtissage','réduction','béchamel','montage','gratinage','repos']::text[], ARRAY['Au gruyère râpé, jusqu''à 400 g pour quatre, à la place du parmesan (marmiton)','Au chèvre : 100 g de fromage de chèvre frais entre les couches, ou une crème de chèvre au pesto (marmiton, deux pages)','À la ricotta et aux épinards : 300 g de ricotta, 450 g d''épinards frais et deux œufs (750g)','Aux carottes râpées, une à deux, ajoutées à la sauce tomate (750g)','Au provolone, 100 g en plus de la mozzarella, avec de l''origan frais et des tomates cerises rôties (chefsimon)','Sans béchamel : quatre cuillerées de crème liquide réparties entre les couches (chefsimon)']::text[], ARRAY['gluten','lait']::text[],
    'Se garde 4 jours au réfrigérateur et se réchauffe par parts, 15 minutes à 180 °C sous aluminium. Elle se coupe mieux froide que chaude. Se congèle 3 mois, crue et montée ou déjà cuite : crue, elle s''enfourne sans décongélation en ajoutant vingt-cinq minutes. Les légumes rôtis et la sauce se préparent 3 jours à l''avance et se congèlent séparément, ce qui ramène le montage à un quart d''heure.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'IT-001'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

