  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les lentilles vertes, les couvrir de trois fois leur volume d''eau froide sans sel, porter à frémissement et cuire vingt à vingt-cinq minutes, jusqu''à ce qu''elles cèdent sous la dent en gardant leur forme, puis égoutter. Elles cuisent à part et à l''eau, pas dans la tomate : l''acidité comme le sel durcissent la peau d''une légumineuse, et une lentille versée crue dans la sauce y resterait ferme une heure plus tard. On les arrête un peu fermes, elles finiront dans la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Tailler l''oignon, la carotte et le céleri en dés de deux à trois millimètres, les verser dans l''huile chaude avec une pincée de sel et les laisser suer dix à douze minutes à feu moyen sans coloration, jusqu''à ce qu''ils soient fondus et translucides. C''est le soffritto du parent, et il compte davantage ici : sans le gras et les sucs d''une viande, ce sont ces trois légumes fondus qui donnent à la sauce son sucre et son corps.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter le concentré de tomate au contact du fond de la sauteuse et le remuer une bonne minute : il fonce, perd son goût de fer et apporte ce que la viande rissolée donnait au parent. Verser ensuite les tomates concassées, l''ail écrasé, le thym et le laurier, et rincer la boîte d''un fond d''eau qu''on verse aussi.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Laisser mijoter vingt minutes à découvert et à petits bouillons, en raclant le fond de temps en temps, jusqu''à ce que la sauce ait perdu son eau libre. La tomate doit réduire seule avant l''arrivée des lentilles : elles boivent du liquide, et une sauce encore claire à ce stade donnerait un plat fade et lâche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter les lentilles égouttées et poursuivre quinze minutes à feu doux. Écraser une louche de lentilles contre la paroi et la remuer dans la sauce : cet écrasement partiel libère leur amidon et lie la sauce, ce qui remplace le collagène et le gras du haché. Saler, poivrer, goûter ; si l''acidité pique encore, une pincée de sucre l''arrondit. Retirer le thym et le laurier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Cuire les spaghetti dans un grand volume d''eau salée — un litre et dix grammes de sel par cent grammes de pâtes — et les égoutter une minute avant le temps du paquet en réservant une louche d''eau. Ni rinçage ni huile : l''amidon resté en surface est ce qui accrochera la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Verser les pâtes dans la sauce avec une petite louche d''eau de cuisson et remuer une minute sur le feu, jusqu''à ce que chaque spaghetti soit enrobé et que la sauce ne reste plus au fond. Servir aussitôt, le parmesan à part pour ceux qui en veulent.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-001', 'recipe_family', 'Spaghetti à la bolognaise de lentilles',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-001', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux lentilles corail, 30 g par personne cuites directement dans la tomate un quart d''heure, pour une sauce plus fondue (marmiton, chefsimon)','Aux champignons de Paris émincés et revenus avec l''oignon, 120 à 300 g pour quatre (chefsimon)','Déglacée au vin rouge, 7 cl pour quatre, avant la tomate (750g), ou mouillée d''un verre de vin blanc avec les tomates (marmiton)','Au poireau émincé avec l''oignon, à la place du céleri, et aux herbes de Provence (marmiton)','Aux tomates séchées, noix de Grenoble concassées et paprika (chefsimon)','Une cuillerée à café de miel dans la sauce pour arrondir l''acidité (marmiton)','Servie avec du parmesan râpé — ou, pour un végétarien strict, un fromage à pâte dure sans présure animale (chefsimon, 750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-001","variants":["Aux lentilles corail, 30 g par personne cuites directement dans la tomate un quart d''heure, pour une sauce plus fondue (marmiton, chefsimon)","Aux champignons de Paris émincés et revenus avec l''oignon, 120 à 300 g pour quatre (chefsimon)","Déglacée au vin rouge, 7 cl pour quatre, avant la tomate (750g), ou mouillée d''un verre de vin blanc avec les tomates (marmiton)","Au poireau émincé avec l''oignon, à la place du céleri, et aux herbes de Provence (marmiton)","Aux tomates séchées, noix de Grenoble concassées et paprika (chefsimon)","Une cuillerée à café de miel dans la sauce pour arrondir l''acidité (marmiton)","Servie avec du parmesan râpé — ou, pour un végétarien strict, un fromage à pâte dure sans présure animale (chefsimon, 750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-001', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('783ca730352980d94dd06ad0703051a8'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":3},"dominant_flavors":["tomate cuite","lentille","légume compoté"],"aroma_families":["tomate_cuite","oignon_compoté","lentille","thym"],"target_textures":["sauce_nappante","pâtes_fermes","lentilles fondantes mais entières"],"signature_ingredients":["Spaghetti secs","Lentille verte sèche, crue","Tomate concassée en conserve","Carotte crue","Céleri branche cru"],"identity_guardrails":["Le soffritto oignon-carotte-céleri fondu au départ est ce qui reste de la bolognaise quand la viande s''en va : sans lui c''est une sauce tomate aux lentilles","Les lentilles cuisent à part, à l''eau non salée, et n''entrent qu''une fois la tomate réduite : versées crues dans l''acide elles restent dures","Une louche de lentilles écrasée lie la sauce : c''est ce qui remplace le gras et le collagène du haché, et pourquoi le plat ne prend ni farine ni crème","Les pâtes finissent dans la sauce avec un peu de leur eau, comme dans le parent ; servies nues sous la sauce, le plat se dissocie"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Blanquette de tofu', 'blanquette de tofu', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Blanquette de tofu', 'Cubes de tofu ferme pochés dans un bouillon de légumes avec carottes, poireau et champignons, liés au roux et à la crème — la blanquette de dinde sans la dinde', ds.id, 'JUM-002',
    'Myko', 'editorial', 4, 20, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', '2564c3d64556c8e036a869f90a403a05',
    '{"sweet":2,"salty":3,"acidic":1,"bitter":0,"umami":2,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":2}'::jsonb, ARRAY['crème','champignon','légumes racines fondus']::text[],
    ARRAY['lacté','champignon_terreux','thym','poireau']::text[], ARRAY['sauce nappante','tofu','légumes tendres']::text[],
    ARRAY['Tofu ferme','Crème fraîche liquide entière','Champignon de Paris frais']::text[], ARRAY['Rien ne colore : légumes et tofu cuisent dans le bouillon, et la sauce reste ivoire — une saisie brune donnerait un sauté en sauce, plus une blanquette','Le tofu se presse avant d''entrer dans le bouillon, sinon il rend son eau dans la sauce et la détend','La liaison est un roux mouillé au bouillon de cuisson et monté à la crème hors du feu : sans elle, il reste un bouillon de légumes au tofu','Bouillon de légumes, jamais de volaille : c''est ce qui fait de ce plat le jumeau végétarien de la blanquette de dinde']::text[],
    ARRAY['pressage','pochage','cuisson au bouillon','roux blanc','liaison au roux','finition crème']::text[], ARRAY['Liée au jaune d''œuf battu dans la crème, avec le jus d''un demi-citron, hors du feu (recette-painperdu)','Aux pommes de terre en gros cubes cuites dans le bouillon avec les carottes, ce qui en fait un plat complet (750g, supertoinette)','Tofu mariné dix minutes à la moutarde puis saisi à l''huile avant d''entrer dans la sauce, et crème de soja à la place de la crème (supertoinette)','Au céleri branche avec les poireaux, liée à la fécule de maïs, avec deux clous de girofle (ptitchef)','Aux pruneaux trempés, ajoutés au mijotage, et nappée d''une cuillerée de crème de soja (750g)','Finie à la ciboulette plutôt qu''au persil (supertoinette)']::text[], ARRAY['gluten','lait','soja']::text[],
    'Se garde 3 jours au réfrigérateur dans un contenant fermé ; réchauffer à feu doux sans bouillir pour que la sauce ne tranche pas. Le tofu, contrairement à la dinde, gagne au deuxième jour : il finit de s''imprégner de la sauce. La congélation est déconseillée telle quelle : le tofu ferme congelé change de texture et devient spongieux, et la crème grène au réchauffage. Si l''on veut congeler, on congèle la base non crémée sans le tofu — légumes et sauce liée, deux mois — et l''on poche le tofu au moment du réchauffage, crème ajoutée en dernier. C''est ce que fait le parent pour la crème, et ce que le tofu impose en plus.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-008'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

