  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les lentilles vertes et les cuire vingt minutes dans trois fois leur volume d''eau froide non salée, à frémissement, jusqu''à ce qu''elles cèdent sous la dent en gardant leur forme ; les égoutter. Dans une autre casserole, cuire le riz complet à grande eau trente-cinq minutes et l''égoutter de même. Les deux cuisent à l''eau et à part : le sel et l''acide de la tomate durciraient la peau des lentilles, et un riz cuit dans la farce y boirait le liquide qui doit rester au jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Détacher douze grandes feuilles du chou en partant de l''extérieur, sans les déchirer, et les blanchir quatre à cinq minutes à l''eau bouillante salée, dans un faitout assez large pour qu''elles y flottent à plat, jusqu''à ce qu''elles se laissent plier sans casser. Les rafraîchir à l''eau froide, les étaler sur un linge et amincir la côte centrale au couteau, à plat : c''est elle qui refuse de se rouler et qui reste dure après une heure de cuisson. Hacher menu le cœur de chou qui reste, il entrera dans la farce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Tailler l''oignon en petits dés et la carotte en brunoise, hacher l''ail et les champignons. Faire suer la moitié de l''oignon, la carotte et l''ail dans deux cuillerées d''huile, huit minutes à feu moyen, puis ajouter les champignons et cuire encore huit à dix minutes, jusqu''à ce que l''eau qu''ils rendent se soit évaporée : versés humides dans la farce, ils la détremperaient et les paquets s''ouvriraient. Ajouter les herbes de Provence et la muscade en fin de cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Réunir dans un saladier les lentilles, le riz, le contenu de la poêle, le cœur de chou haché et le persil ciselé ; saler, poivrer, laisser tiédir, puis incorporer les œufs battus. On attend que la farce soit tiède avant l''œuf, sinon il coagule au contact et ne lie plus rien. Écraser une poignée de lentilles à la fourchette dans le mélange : leur amidon donne à la farce la tenue que le gras de la viande donnait au parent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Poser une feuille côte vers soi, déposer une grosse cuillerée de farce au tiers inférieur, rabattre les côtés puis rouler serré en un paquet fermé, pliure dessous ; compter deux paquets par personne. Ficeler ceux qui menacent de s''ouvrir. Un paquet lâche se déroule au premier frémissement et la farce part dans le jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Faire fondre le reste de l''oignon dans le reste d''huile au fond d''une cocotte, verser la tomate concassée, le bouillon de légumes et le laurier, porter à frémissement. Ranger les paquets serrés les uns contre les autres, pliure dessous, en une seule couche : serrés, ils se tiennent mutuellement fermés. Le liquide doit arriver à mi-hauteur, pas plus — ce sont des paquets qu''on braise, pas une soupe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couvrir et tenir le feu au plus bas cinquante minutes, en arrosant le dessus des paquets avec le jus toutes les quinze minutes. Le chou doit devenir fondant sous la pointe du couteau et le jus, réduit de moitié, napper la cuillère. Laisser reposer dix minutes hors du feu avant de servir, deux paquets par assiette, nappés du jus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-004', 'recipe_family', 'Chou farci végétarien',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-004', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au quinoa rouge et aux lentilles corail cuits ensemble dans un bouillon au concentré de tomate, relevés de piment d''Espelette, paquets cuits au four arrosés du jus de cuisson (lacerisesurlemaillot)','Farce aux champignons, aubergine frite, pignons, chapelure et ricotta, montée en moules chemisés de feuilles et cuite une heure au four (marmiton)','Rouleaux au millet, aux noix et à la sauce soja, gratinés à l''emmental vingt minutes au four (menu-vegetarien)','Champignons de Paris en conserve plutôt que frais (ffcuisine)','Cuisson au four à sec plutôt qu''en cocotte : vingt à soixante minutes selon la taille des paquets (marmiton, menu-vegetarien)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-004","variants":["Au quinoa rouge et aux lentilles corail cuits ensemble dans un bouillon au concentré de tomate, relevés de piment d''Espelette, paquets cuits au four arrosés du jus de cuisson (lacerisesurlemaillot)","Farce aux champignons, aubergine frite, pignons, chapelure et ricotta, montée en moules chemisés de feuilles et cuite une heure au four (marmiton)","Rouleaux au millet, aux noix et à la sauce soja, gratinés à l''emmental vingt minutes au four (menu-vegetarien)","Champignons de Paris en conserve plutôt que frais (ffcuisine)","Cuisson au four à sec plutôt qu''en cocotte : vingt à soixante minutes selon la taille des paquets (marmiton, menu-vegetarien)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-004', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d1c35ccfebce558b6ec456dbebb7eb19'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":3},"dominant_flavors":["chou fondant","lentille","champignon","tomate cuite"],"aroma_families":["végétal cuit","champignon_terreux","tomate_cuite","aromates verts"],"target_textures":["feuilles fondantes","farce moelleuse et serrée","jus court et nappant"],"signature_ingredients":["Chou vert frais","Lentille verte sèche, crue","Champignon de Paris frais"],"identity_guardrails":["Les feuilles de chou vert entières enveloppent la farce, en paquets fermés : émincé et mélangé aux lentilles, ce n''est plus un chou farci mais une potée","La farce tient sur les lentilles vertes et les champignons liés au riz et à l''œuf, sans haché végétal du commerce — les quatre pages s''en passent","Les champignons sont cuits à sec avant d''entrer dans la farce, sinon ils la détrempent et les paquets s''ouvrent","La cuisson est un braisage long à couvert dans un mouillement court de tomate et de bouillon, comme le parent, pas un rôtissage à sec"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Mafé végétarien', 'mafe vegetarien', 'Mali/Sénégal', 'Mali/Sénégal',
     'meal', 'ragoût à l arachide', 'domestic_standard', 'nutty_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Mafé végétarien', 'Patate douce, carottes, chou et pois chiches mijotés dans la sauce d''arachide et de tomate concentrée du mafé, servis sur du riz — le jumeau végétarien du mafé de bœuf', ds.id, 'JUM-005',
    'Myko', 'editorial', 8, 25, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', '9e640d1931504d6c0b9f2154ca38f506',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":2,"pungency":2,"richness":4,"freshness":1,"intensity":4}'::jsonb, ARRAY['arachide','patate douce','tomate concentrée','pois chiche']::text[],
    ARRAY['arachide','oignon_compoté','tomate_cuite','piment']::text[], ARRAY['sauce_onctueuse','légumes_entiers','pois chiches fondants']::text[],
    ARRAY['Pâte d’arachide pure','Patate douce crue, épluchée','Pois chiche cuit, égoutté','Tomate concentrée']::text[], ARRAY['La pâte d''arachide est pure et non sucrée, délayée dans le bouillon chaud et jamais versée telle quelle : un beurre de cacahuète sucré fait un autre plat','La sauce réduit jusqu''à napper et à laisser perler l''huile d''arachide, comme le parent — un mafé clair est une soupe','Les légumes entrent selon leur temps de cuisson, carotte et chou avant la patate douce, et restent entiers','Les pois chiches remplacent le bœuf et entrent en dernier, déjà cuits : versés au départ ils s''écraseraient et lieraient la sauce en purée']::text[],
    ARRAY['suer','friture de concentré','mijotage','légumes séquencés','réduction']::text[], ARRAY['Mafé de légumes sans légumineuse, la patate douce en tenant la place — la lecture de cinq pages sur six (bonduelle, lescommis, sabnpepper, marmiton, menu-vegetarien)','Avec de la chair de tomate en plus du concentré : 400 g de pulpe pour quatre, deux tomates fraîches ou une boîte (lescommis, sabnpepper, marmiton)','Au gingembre frais râpé avec l''ail, 20 g pour quatre (lescommis, recettesetcabas)','Avec des pommes de terre en plus de la patate douce, quatre pour six (bonduelle, sabnpepper)','À l''aubergine en gros morceaux avec les autres légumes, cuite en cocotte-minute (marmiton)','Aux feuilles de blettes ajoutées en fin de cuisson, relevé de cumin et de flocons de piment (menu-vegetarien)','Arrosé d''un filet de jus de citron vert au service, sur du riz avec des carottes seules (recettesetcabas)','Servi sur de la semoule plutôt que sur du riz, parsemé de persil (lescommis)','Une feuille de laurier dans le bouillon (bonduelle)']::text[], ARRAY['arachide']::text[],
    'Se garde 3 jours au réfrigérateur dans un récipient fermé, la durée du parent, et gagne au deuxième jour, la sauce d''arachide finissant d''imprégner les légumes. Aucune des six pages du dossier ne dit un mot de la conservation : la durée vient du parent et de rien d''autre, et on ne l''allonge pas sur une déduction. Se congèle 3 mois sans dommage : pois chiches et sauce d''arachide supportent le froid. La patate douce ramollit un peu à la décongélation, ce qui ne gêne pas un plat en sauce. Réchauffer à couvert et à feu doux avec un fond d''eau : la sauce a épaissi en refroidissant et attacherait. Cuire le riz au moment du service.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-155'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

