  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Mafé de légumes sans légumineuse, la patate douce en tenant la place — la lecture de cinq pages sur six (bonduelle, lescommis, sabnpepper, marmiton, menu-vegetarien)','Avec de la chair de tomate en plus du concentré : 400 g de pulpe pour quatre, deux tomates fraîches ou une boîte (lescommis, sabnpepper, marmiton)','Au gingembre frais râpé avec l''ail, 20 g pour quatre (lescommis, recettesetcabas)','Avec des pommes de terre en plus de la patate douce, quatre pour six (bonduelle, sabnpepper)','À l''aubergine en gros morceaux avec les autres légumes, cuite en cocotte-minute (marmiton)','Aux feuilles de blettes ajoutées en fin de cuisson, relevé de cumin et de flocons de piment (menu-vegetarien)','Arrosé d''un filet de jus de citron vert au service, sur du riz avec des carottes seules (recettesetcabas)','Servi sur de la semoule plutôt que sur du riz, parsemé de persil (lescommis)','Une feuille de laurier dans le bouillon (bonduelle)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-005","variants":["Mafé de légumes sans légumineuse, la patate douce en tenant la place — la lecture de cinq pages sur six (bonduelle, lescommis, sabnpepper, marmiton, menu-vegetarien)","Avec de la chair de tomate en plus du concentré : 400 g de pulpe pour quatre, deux tomates fraîches ou une boîte (lescommis, sabnpepper, marmiton)","Au gingembre frais râpé avec l''ail, 20 g pour quatre (lescommis, recettesetcabas)","Avec des pommes de terre en plus de la patate douce, quatre pour six (bonduelle, sabnpepper)","À l''aubergine en gros morceaux avec les autres légumes, cuite en cocotte-minute (marmiton)","Aux feuilles de blettes ajoutées en fin de cuisson, relevé de cumin et de flocons de piment (menu-vegetarien)","Arrosé d''un filet de jus de citron vert au service, sur du riz avec des carottes seules (recettesetcabas)","Servi sur de la semoule plutôt que sur du riz, parsemé de persil (lescommis)","Une feuille de laurier dans le bouillon (bonduelle)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-005', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('9e640d1931504d6c0b9f2154ca38f506'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"nutty_savory","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":2,"pungency":2,"richness":4,"freshness":1,"intensity":4},"dominant_flavors":["arachide","patate douce","tomate concentrée","pois chiche"],"aroma_families":["arachide","oignon_compoté","tomate_cuite","piment"],"target_textures":["sauce_onctueuse","légumes_entiers","pois chiches fondants"],"signature_ingredients":["Pâte d’arachide pure","Patate douce crue, épluchée","Pois chiche cuit, égoutté","Tomate concentrée"],"identity_guardrails":["La pâte d''arachide est pure et non sucrée, délayée dans le bouillon chaud et jamais versée telle quelle : un beurre de cacahuète sucré fait un autre plat","La sauce réduit jusqu''à napper et à laisser perler l''huile d''arachide, comme le parent — un mafé clair est une soupe","Les légumes entrent selon leur temps de cuisson, carotte et chou avant la patate douce, et restent entiers","Les pois chiches remplacent le bœuf et entrent en dernier, déjà cuits : versés au départ ils s''écraseraient et lieraient la sauce en purée"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Seitan alla cacciatora', 'seitan alla cacciatora', 'Italie', 'Italie',
     'meal', 'plat mijoté', 'named_traditional_dish', 'tomato_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Seitan alla cacciatora', 'Morceaux de seitan farinés et dorés, mijotés dans une sauce chasseur au vin rouge, à la tomate, aux olives et au romarin — le jumeau végétarien du pollo alla cacciatora', ds.id, 'JUM-006',
    'Myko', 'editorial', 6, 25, 40, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '09513dce850ec05eea7e911b96acda80',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":2,"freshness":2,"intensity":4}'::jsonb, ARRAY['tomate','vin rouge réduit','olive','romarin']::text[],
    ARRAY['tomate_cuite','vin_rouge_réduit','romarin','oignon_compoté','ail']::text[], ARRAY['sauce_rustique','seitan ferme à croûte fondue','légumes fondants']::text[],
    ARRAY['Seitan','Tomate concassée en conserve','Vin rouge sec','Olive noire dénoyautée','Romarin frais']::text[], ARRAY['Le seitan est fariné et doré avant d''entrer dans la sauce : nu, il reste lisse, gris et glissant','Le vin rouge réduit avant la tomate, comme dans le parent — versé avec elle il reste aigre','Cuisson mijotée à couvert puis découverte, sans crème : la sauce nappe, elle ne baigne pas','Les olives sont obligatoires ici : les trois pages en portent, et c''est ce qui reste de la cacciatora quand le poulet s''en va']::text[],
    ARRAY['enrobage à la farine','saisie','soffritto','déglaçage','mijotage','réduction']::text[], ARRAY['Aux champignons de Paris, 350 g revenus avec l''oignon — la garniture du parent, qu''aucune page de seitan ne reprend','Seitan mariné une heure dans le vin rouge avec clous de girofle, baies de genièvre, thym, origan et poivre en grains, puis épongé et fariné ; concentré de tomate dans le bouillon plutôt que tomate concassée, câpres dessalées et olives vertes (petitchef)','En blanc, sans tomate : déglacé au vin blanc, aux olives taggiasche, à la sauge et au romarin, réduit à sec en fin de cuisson (academia)','Seitan fait maison à la farine de gluten et aux pommes de terre, poché une heure et demie dans un bouillon de légumes au kombu (academia)','Servi avec des tranches de pain pour saucer (vegolosi)']::text[], ARRAY['gluten']::text[],
    'Se garde 3 jours au réfrigérateur dans un récipient fermé — c''est ce que dit le parent, et aucune des trois pages de seitan ne parle de conservation : la durée vient du parent, pas du dossier — et gagne au deuxième jour, le seitan finissant de boire la sauce. Se congèle 3 mois : le seitan, contrairement au tofu, garde sa texture au froid, et une sauce tomate au vin sans crème ne tranche pas. Réchauffer à couvert et à feu doux avec un fond d''eau, la sauce ayant épaissi. C''est ce que fait physiquement un ragoût de gluten en sauce tomate, et c''est ce qu''on écrit.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-095'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
