  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux champignons de Paris, 350 g revenus avec l''oignon — la garniture du parent, qu''aucune page de seitan ne reprend','Seitan mariné une heure dans le vin rouge avec clous de girofle, baies de genièvre, thym, origan et poivre en grains, puis épongé et fariné ; concentré de tomate dans le bouillon plutôt que tomate concassée, câpres dessalées et olives vertes (petitchef)','En blanc, sans tomate : déglacé au vin blanc, aux olives taggiasche, à la sauge et au romarin, réduit à sec en fin de cuisson (academia)','Seitan fait maison à la farine de gluten et aux pommes de terre, poché une heure et demie dans un bouillon de légumes au kombu (academia)','Servi avec des tranches de pain pour saucer (vegolosi)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-006","variants":["Aux champignons de Paris, 350 g revenus avec l''oignon — la garniture du parent, qu''aucune page de seitan ne reprend","Seitan mariné une heure dans le vin rouge avec clous de girofle, baies de genièvre, thym, origan et poivre en grains, puis épongé et fariné ; concentré de tomate dans le bouillon plutôt que tomate concassée, câpres dessalées et olives vertes (petitchef)","En blanc, sans tomate : déglacé au vin blanc, aux olives taggiasche, à la sauge et au romarin, réduit à sec en fin de cuisson (academia)","Seitan fait maison à la farine de gluten et aux pommes de terre, poché une heure et demie dans un bouillon de légumes au kombu (academia)","Servi avec des tranches de pain pour saucer (vegolosi)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-006', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('09513dce850ec05eea7e911b96acda80'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"tomato_herbal","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":2,"freshness":2,"intensity":4},"dominant_flavors":["tomate","vin rouge réduit","olive","romarin"],"aroma_families":["tomate_cuite","vin_rouge_réduit","romarin","oignon_compoté","ail"],"target_textures":["sauce_rustique","seitan ferme à croûte fondue","légumes fondants"],"signature_ingredients":["Seitan","Tomate concassée en conserve","Vin rouge sec","Olive noire dénoyautée","Romarin frais"],"identity_guardrails":["Le seitan est fariné et doré avant d''entrer dans la sauce : nu, il reste lisse, gris et glissant","Le vin rouge réduit avant la tomate, comme dans le parent — versé avec elle il reste aigre","Cuisson mijotée à couvert puis découverte, sans crème : la sauce nappe, elle ne baigne pas","Les olives sont obligatoires ici : les trois pages en portent, et c''est ce qui reste de la cacciatora quand le poulet s''en va"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Goulash végétarien aux haricots (babgulyás)', 'goulash vegetarien aux haricots babgulyas', 'Hongrie', 'Hongrie',
     'meal', 'ragoût de haricots', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Goulash végétarien aux haricots (babgulyás)', 'Soupe-ragoût hongroise au paprika où des haricots blancs remplacent le bœuf, avec pommes de terre, carottes, poivron et tomate dans un bouillon rouge — le jumeau végétarien du goulash', ds.id, 'JUM-007',
    'Myko', 'editorial', 8, 25, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', '2423d8363bcbdbffe817bcb3c1f0b638',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":1,"pungency":2,"richness":2,"freshness":1,"intensity":3}'::jsonb, ARRAY['paprika doux','oignon fondu','haricot blanc','tomate cuite']::text[],
    ARRAY['paprika','oignon compoté','fumé','tomate cuite']::text[], ARRAY['haricots fondants mais entiers','pomme de terre juste tenue','bouillon rouge lié']::text[],
    ARRAY['Haricot blanc cuit, égoutté','Paprika doux','Oignon jaune cru','Pomme de terre crue, épluchée']::text[], ARRAY['Sans paprika doux en quantité — 15 g pour huit, jetés hors du feu — ce n''est qu''une soupe de haricots : la couleur et le parfum ne viennent de rien d''autre','L''oignon fondu et une louche de haricots écrasés lient le bouillon : ni farine ni crème dans la marmite, qui en feraient un paprikás','Les haricots entrent en dernier, déjà cuits, et restent entiers ; cuits une heure dans le paprika ils font une purée','Le bouillon reste franchement liquide et se sert à la louche : c''est une soupe-ragoût, pas une sauce']::text[],
    ARRAY['fondue d''oignons','paprika hors du feu','mijotage','ajout tardif des légumes','liaison par écrasement']::text[], ARRAY['Au tofu fumé, 200 g en dés revenus avec les légumes, avec de la patate douce et du thym — forme absente du catalogue (bonduelle)','Aux dés de soja déshydratés, 50 g trempés la veille, cuits avec les haricots secs, à l''huile de coco, avec racine de persil, chou-rave et céleri-rave — forme absente du catalogue (cookpad)','Aux haricots secs trempés la veille et cuits dans leur eau, qui sert ensuite de bouillon (mindenmentes, cookpad)','Avec des pâtes à potage — csipetke, galuska ou lebbencs — pochées dedans en fin de cuisson (urban-eve)','Relevé de pâte de piment hongroise, deux cuillerées pour dix, et servi avec une crème végétale (mindenmentes)','Aux haricots pinto plutôt que blancs, avec racine de persil et vert de céleri, parsemé de persil frais (mindenmentes)','Au poivron vert plutôt que rouge (mindenmentes)']::text[], ARRAY['lait']::text[],
    'Se garde 3 à 4 jours au réfrigérateur dans un récipient fermé, et gagne à être réchauffé le lendemain — le paprika continue de diffuser dans le bouillon, ce que le parent dit aussi. Se congèle 3 mois, en retirant les pommes de terre avant congélation comme pour le parent : elles ressortent granuleuses ; les haricots, eux, supportent le froid sans s''écraser. Réchauffer à couvert et à feu doux en rallongeant d''un peu de bouillon, sans faire rebouillir pour ne pas défaire les haricots. La crème, si l''on en sert, va dans l''assiette et non dans la marmite, pour que le reste se conserve tel quel.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-295'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
