  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler l''oignon en petits dés, les carottes en rondelles épaisses, le poivron en lanières, les tomates en dés, les pommes de terre en gros quartiers ; hacher l''ail ; rincer et égoutter les haricots. Les quartiers de pommes de terre sont gros pour la même raison que dans le parent : petits, ils se délitent et rendent le bouillon farineux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fondre l''oignon dans l''huile, à feu doux et à couvert, quinze minutes, jusqu''à ce qu''il soit translucide et sucré sans couleur. Cette fondue est ce qui lie un goulash, et le jumeau en a autant besoin que le parent : sans viande ni farine, c''est elle et l''amidon des haricots qui donneront du corps au bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Retirer la marmite du feu, attendre une minute, puis jeter le paprika doux, le paprika fumé, le cumin et l''ail dans le gras tiède et remuer vivement pour les enrober. Le paprika brûle très bas et son amertume ne se rattrape pas : hors du feu, il s''ouvre dans la graisse et donne au plat sa couleur rouge profonde. Le fumé tient ici la place de la fumée que la viande apportait.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre sur feu moyen, ajouter le poivron et les tomates, laisser rendre leur eau deux ou trois minutes, puis verser le bouillon de légumes, ajouter les carottes et le laurier. Porter à frémissement et cuire quinze minutes à couvert ; les carottes partent en premier parce qu''elles sont les plus longues.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter les pommes de terre et cuire vingt minutes, à petits frémissements, jusqu''à ce qu''un quartier cède sous la lame. Ajouter alors les haricots égouttés pour les dix dernières minutes seulement : déjà cuits, ils n''ont qu''à se réchauffer et à prendre le paprika, et versés au départ ils s''écraseraient. Écraser une louche de haricots contre la paroi et la remuer dans le bouillon : leur amidon le lie, et c''est ce qui remplace ici la longue réduction du parent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Saler — les haricots n''ont pas été salés en boîte comme la viande l''aurait été —, poivrer, retirer le laurier, et laisser reposer dix minutes hors du feu, le temps que les pommes de terre finissent de s''imbiber. Servir à la louche en assiette creuse, avec, pour qui le veut, une cuillerée de crème fraîche déposée dans l''assiette et non dans la marmite.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-007', 'recipe_family', 'Goulash végétarien aux haricots (babgulyás)',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-007', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
