  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Couper le pied terreux des champignons, les essuyer sans les laver — un champignon lavé boit l''eau et ne dore plus — et les tailler en quartiers plutôt qu''en lamelles fines. Ici le champignon tient la place de la viande : en quartiers il garde une mâche sous la dent, en lamelles il fond et la sauce devient une soupe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer la moitié de l''huile dans une grande poêle à feu vif et y jeter les champignons en deux fournées, sans sel, sans les remuer pendant deux minutes puis en les faisant sauter jusqu''à ce qu''ils soient dorés sur leurs faces et que leur eau se soit évaporée. C''est le geste qui remplace la saisie du bœuf : entassés ou salés, ils rendent leur eau d''un coup et bouillent gris au lieu de rôtir, et la sauce n''aura plus de sucs sur lesquels s''appuyer. Les réserver.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Baisser à feu moyen, verser le reste de l''huile et faire fondre l''oignon émincé six à huit minutes, jusqu''à ce qu''il soit translucide et commence à blondir. Ajouter l''ail haché une minute. L''oignon est ici de moitié plus abondant que dans le parent, et il ne se contente pas de parfumer : fondu, il fait avec le champignon le corps du plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Singer avec la farine, remuer une minute pour qu''elle cuise, puis déglacer au vin blanc en grattant le fond. Ajouter le concentré de tomate et le laisser foncer trente secondes au contact de la poêle avant de mouiller : sans les sucs bruns d''une viande, c''est lui qui donne à la sauce sa couleur et son fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le bouillon de légumes, porter à petits bouillons et laisser réduire cinq minutes jusqu''à ce que la sauce nappe la cuillère. Remettre les champignons avec le jus qu''ils ont rendu au repos, et les laisser deux minutes dans la sauce pour qu''ils s''en imprègnent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Baisser le feu au minimum et incorporer la crème, le paprika puis la moutarde, hors ébullition. La moutarde entre en dernier et ne bout jamais, sinon elle perd son piquant et laisse un goût plat : c''est la règle du parent, et elle ne change pas parce que la viande s''en est allée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Saler, poivrer, parsemer de persil et servir aussitôt sur un riz, des pâtes ou une purée. Contrairement au parent, rien ici ne surcuit si l''on attend cinq minutes — mais la sauce épaissit vite en refroidissant, et une cuillerée de bouillon la détend au moment de servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-033', 'recipe_family', 'Stroganoff de champignons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-033', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au lait de coco à la place de la crème et du bouillon, 800 ml pour quatre, réduit vingt minutes à feu vif, pour une version végétalienne (marciatack.fr, sharkninja.fr)','À la crème de cajou : 140 g de noix de cajou trempées mixées avec le bouillon, du tamari et du vinaigre balsamique, sur des fettuccine (menu-vegetarien.com)','À la crème de soja ou d''avoine, avec du sirop d''érable, de la sauce soja, du thym et du laurier, servi sur des linguine (larecetteparfaite.com)','Avec 200 g de tofu fumé sauté avec les champignons, pour retrouver une protéine, servi sur une purée à l''huile d''olive (lescommis.com)','Un jus de citron incorporé avec la crème, pour l''acidité de la crème aigre du plat russe (marciatack.fr, menu-vegetarien.com, sharkninja.fr)','Au paprika fumé en plus du doux (larecetteparfaite.com)','Lié à la fécule de maïs plutôt qu''à la farine, pour une version sans gluten (sharkninja.fr)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-033","variants":["Au lait de coco à la place de la crème et du bouillon, 800 ml pour quatre, réduit vingt minutes à feu vif, pour une version végétalienne (marciatack.fr, sharkninja.fr)","À la crème de cajou : 140 g de noix de cajou trempées mixées avec le bouillon, du tamari et du vinaigre balsamique, sur des fettuccine (menu-vegetarien.com)","À la crème de soja ou d''avoine, avec du sirop d''érable, de la sauce soja, du thym et du laurier, servi sur des linguine (larecetteparfaite.com)","Avec 200 g de tofu fumé sauté avec les champignons, pour retrouver une protéine, servi sur une purée à l''huile d''olive (lescommis.com)","Un jus de citron incorporé avec la crème, pour l''acidité de la crème aigre du plat russe (marciatack.fr, menu-vegetarien.com, sharkninja.fr)","Au paprika fumé en plus du doux (larecetteparfaite.com)","Lié à la fécule de maïs plutôt qu''à la farine, pour une version sans gluten (sharkninja.fr)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-033', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e9e120cb7da06b6c338f0d1b3332e631'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":1,"pungency":3,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["champignon rôti","crème","moutarde","oignon fondu"],"aroma_families":["champignon","oignon_compoté","moutarde","paprika","crème"],"target_textures":["champignons dorés et fermes","sauce_nappante","oignon fondu"],"signature_ingredients":["Champignon de Paris frais","Crème fraîche épaisse","Moutarde de Dijon","Paprika doux"],"identity_guardrails":["Les champignons se sautent à feu vif, sans sel, en deux fournées, jusqu''à évaporation de leur eau : c''est la saisie du bœuf transposée, et un champignon bouilli fait une soupe","La moutarde entre en dernier et ne bout jamais, comme dans le parent","Bouillon de légumes et non de bœuf : c''est la seule autre forme animale du parent, et elle part avec la viande","Crème fraîche épaisse, pas lait de coco : le coco fait une autre sauce et un autre plat"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Cake aux olives et à la feta', 'cake aux olives et a la feta', 'France — cuisine domestique', 'France — cuisine domestique',
     'meal', 'cake salé', 'domestic_standard', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Cake aux olives et à la feta', 'Le cake salé de la lignée FR-028 où la feta prend la place du jambon : même appareil farine-œufs-lait, mêmes olives vertes, même gruyère, même heure de four.', ds.id, 'JUM-041',
    'Myko', 'editorial', 6, 15, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '2b8492dc4569bd75883f90e1508defe2',
    '{"sweet":1,"salty":4,"acidic":2,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['olive_saumurée','feta_lactique','fromage_fondu']::text[],
    ARRAY['olive_verte','feta','mie_dorée']::text[], ARRAY['mie_moelleuse','garniture_en_dés','croûte_dorée']::text[],
    ARRAY['Feta','Olive verte dénoyautée','Gruyère râpé']::text[], ARRAY['Sans olives il ne reste qu''un cake à la feta : c''est leur sel et leur amertume qui donnent au plat son nom, et deux pages du dossier les prennent vertes comme la lignée le fait.','La feta se taille en cubes d''un centimètre et ne s''émiette jamais : émiettée elle disparaît dans la mie, et le cake perd la garniture visible que les dés de jambon donnaient au parent.','La levure chimique n''est pas négociable : cinq pages sur neuf mettent un sachet entier et un appareil aussi chargé de garniture sort compact sans elle.','Aucune viande, aucun poisson : les deux pages au saumon et au jambon que la recherche a ramenées ont été écartées avant relevé, et c''est ce qui fait de ce cake le jumeau végétarien de FR-028.']::text[],
    ARRAY['appareil à cake salé','enrobage','cuisson au four','égouttage','démoulage à tiède']::text[], ARRAY['Aux olives noires, six pages du dossier sur neuf, de 60 à 100 g déclarés selon les pages, soit 7,5 à 20 g par personne — la mie en sort plus sombre et plus amère (marmiton.org, chefsimon.com, 750g.com)','Aux tomates séchées ou confites, de 50 g pour quatre à 130 g pour six, ajoutées à la garniture (marmiton.org, chefsimon.com, 750g.com)','Au basilic frais ou à l''origan séché dans l''appareil, une cuillerée à soupe pour six (marmiton.org, chefsimon.com, 750g.com)','Moitié huile d''olive, moitié beurre clarifié, 100 g de chacun pour six : mie plus courte et plus riche (marmiton.org)','Avec une courgette et un oignon revenus à la poêle avant d''être incorporés, ou 500 g de haricots verts, ou les fanes d''une botte de radis (chefsimon.com, 750g.com)','Monté au yaourt et au bicarbonate plutôt qu''au lait et à la levure chimique (chefsimon.com)','Relevé d''une pointe de curry ou de tandoori à la place du poivre (marmiton.org, 750g.com)']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Quatre jours au réfrigérateur, enveloppé serré dans du film ou du papier d''aluminium : à l''air libre la mie sèche en une demi-journée, et la feta la rend plus humide, donc plus fragile, que celle du cake au jambon. Il se tranche mieux le lendemain, quand la mie a fini de se serrer autour des cubes. Se congèle 3 mois, entier ou en tranches séparées par du papier cuisson — les tranches se réchauffent alors sans décongélation, dix minutes à 150 °C, ce que le micro-ondes ne rend jamais aussi bien. La feta ressort un peu plus granuleuse après congélation, ce qui ne se voit pas dans une tranche tiède. Se sert tiède ou froid, jamais brûlant : à chaud la feta est molle et la tranche s''effrite. Aucune des neuf pages du dossier ne dit un mot de la conservation ; ces durées sont celles que ce type de cake tient physiquement, et on le dit plutôt que de faire semblant de les avoir lues.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'FR-028'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'farine de ble t55' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Farine de blé T55', 200, 'g', 'required',
     'pâte', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oeuf cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Œuf cru', 4, 'u', 'required',
     'pâte', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'feta' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
