  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les lentilles vertes à l''eau froide, les couvrir de trois fois leur volume d''eau NON salée et les cuire vingt-cinq minutes à petits frémissements. Les arrêter tendres et entières : le sel et l''ébullition franche font éclater leur peau, et une lentille éclatée se délite sous la purée, ce qui donne un plat à un seul étage au lieu de deux. Les égoutter en gardant deux louches de leur eau de cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Prévoir 950 g de pommes de terre avant épluchage pour obtenir les 810 g déclarés. Les éplucher, les couper en morceaux de la taille d''une grosse noix, les couvrir d''eau froide salée et porter à ébullition. Vingt à vingt-cinq minutes plus tard, la lame d''un couteau doit traverser sans résistance. Le départ à froid fait cuire le cœur et le bord au même rythme, ce qu''une mise à l''eau bouillante ne donne pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ces deux cuissons, faire fondre l''oignon finement émincé dans l''huile d''olive à feu moyen, une dizaine de minutes, sans le laisser prendre couleur : on cherche son sucre, pas son amertume. Chez le parent, c''est la graisse du confit qui tenait ce rôle ; la lentille n''en rend aucune, d''où l''huile. Ajouter l''ail haché pour une minute à peine.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser les lentilles égouttées sur l''oignon, poivrer largement, saler de la moitié des huit grammes et laisser prendre trois minutes ensemble. Mouiller d''une louche d''eau de cuisson, puis écraser grossièrement un tiers des lentilles à la fourchette directement dans la sauteuse. Ce tiers écrasé est ce qui lie la couche du bas : sans lui, la garniture reste un tas de grains secs sur lequel la purée glisse, là où le confit tenait tout seul par sa graisse. Ajouter le persil ciselé hors du feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Égoutter les pommes de terre et les remettre trente secondes sur la plaque éteinte, casserole découverte, le temps que la vapeur résiduelle s''échappe — montée sur des morceaux encore humides, la purée tourne à la colle. Les passer au moulin à légumes ou au presse-purée ; le robot, lui, cisaille l''amidon et donne une pâte élastique. Ajouter le beurre par petits morceaux, puis le lait chaud en plusieurs fois jusqu''à ce que la purée retombe en ruban. Râper la muscade et rectifier le sel.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Tasser à peine la garniture de lentilles au fond d''un plat à gratin de deux litres environ. Poser la purée par cuillerées espacées, puis les relier entre elles à la spatule au lieu de l''étaler d''un bord à l''autre : étalée d''un seul geste, elle entraîne les lentilles avec elle et les deux étages se mélangent. Strier la surface à la fourchette, ce sont les crêtes qui brunissent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Semer le comté râpé sur toute la surface et enfourner à 190 °C pour vingt-cinq à trente minutes. Le gratin est prêt quand la croûte est franchement brune et que les bords bouillonnent. Un dessus encore pâle sur un cœur déjà chaud se règle par deux minutes de gril, sans quitter le four des yeux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Sortir le plat et attendre dix minutes avant de servir. Ces dix minutes ne sont pas une coquetterie : brûlantes, les deux couches glissent l''une sur l''autre et la part s''affaisse dans l''assiette ; tiédies, elles se découpent net et gardent leurs deux étages visibles.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-043', 'recipe_family', 'Parmentier de lentilles',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-043', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux lentilles corail plutôt qu''aux vertes, 120 g pour trois, plus fondantes et qui se défont en purée (chefsimon.com)','Avec deux carottes fondues dans l''oignon, ce que font deux des trois pages structurelles — toutes deux de chefsimon — et que le parent ne fait pas (chefsimon.com)','En ragù de lentilles : tomates concassées, concentré, poireau, céleri, laurier et cumin sous la purée (chefsimon.com)','Purée enrichie de crème fraîche ou de fromage à tartiner en plus du lait, une cuillerée pour quatre (marmiton.org)','À la patate douce, entière ou pour moitié, à la place de la pomme de terre — un autre plat sous le même nom (chefsimon.com)','À la courge butternut mêlée à la purée, 800 g pour trois (chefsimon.com)','Un brin de romarin dans les lentilles pendant leur cuisson (chefsimon.com)','Aux lardons fumés revenus avec les échalotes avant les lentilles — c''est la version carnée du même montage, et c''est précisément ce que ce jumeau retire (marmiton.org)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-043","variants":["Aux lentilles corail plutôt qu''aux vertes, 120 g pour trois, plus fondantes et qui se défont en purée (chefsimon.com)","Avec deux carottes fondues dans l''oignon, ce que font deux des trois pages structurelles — toutes deux de chefsimon — et que le parent ne fait pas (chefsimon.com)","En ragù de lentilles : tomates concassées, concentré, poireau, céleri, laurier et cumin sous la purée (chefsimon.com)","Purée enrichie de crème fraîche ou de fromage à tartiner en plus du lait, une cuillerée pour quatre (marmiton.org)","À la patate douce, entière ou pour moitié, à la place de la pomme de terre — un autre plat sous le même nom (chefsimon.com)","À la courge butternut mêlée à la purée, 800 g pour trois (chefsimon.com)","Un brin de romarin dans les lentilles pendant leur cuisson (chefsimon.com)","Aux lardons fumés revenus avec les échalotes avant les lentilles — c''est la version carnée du même montage, et c''est précisément ce que ce jumeau retire (marmiton.org)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-043', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('98de1ea4be6d362f32aa83d4ee575896'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"rich_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["lentille","oignon fondu","comté gratiné","beurre"],"aroma_families":["lentille","oignon compoté","croûte grillée","muscade"],"target_textures":["lentilles fondantes mais entières","purée souple","croûte croustillante"],"signature_ingredients":["Lentille verte sèche, crue","Pomme de terre crue, épluchée","Comté"],"identity_guardrails":["Deux couches distinctes, lentilles dessous et purée dessus : mélangées, c''est une autre préparation.","Un tiers des lentilles est écrasé dans la sauteuse — c''est ce qui lie la couche du bas, là où la graisse du confit tenait toute seule.","La lentille est verte et cuite entière : la corail se défait d''elle-même et donnerait deux purées superposées.","Une croûte de comté franchement brune : un parmentier servi sans gratiner n''est pas fini.","Le féculent est la pomme de terre : les pages du dossier qui montent une patate douce ou un chou-fleur portent le nom sans être le plat."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Courgettes farcies aux lentilles', 'courgettes farcies aux lentilles', 'France', 'France',
     'meal', 'plat au four', 'domestic_standard', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Courgettes farcies aux lentilles', 'Des barquettes de courgette évidées, garnies d''une farce de lentilles vertes, d''oignon et de feta relevée au cumin, rôties au four dans un fond de tomate — le jumeau végétarien des courgettes farcies.', ds.id, 'JUM-051',
    'Myko', 'editorial', 4, 25, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '017b0d657a0b6ec725e40236426d2cbf',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['lentille','courgette rôtie','feta','cumin']::text[],
    ARRAY['cumin','huile_olive','végétal cuit','herbacé']::text[], ARRAY['barquettes fondantes à peau tendue','farce moelleuse et grenue','dessus doré et croustillant']::text[],
    ARRAY['Courgette fraîche','Lentille verte sèche, crue','Feta']::text[], ARRAY['La courgette reste une barquette entière qu''on garnit : coupée en dés et mélangée aux lentilles, ce n''est plus une courgette farcie mais une poêlée','La lentille verte tient le rôle du haché et doit garder son grain — cuite jusqu''à la purée, ou remplacée par de la corail, la farce devient un appareil','La pulpe de courgette est desséchée à la poêle avant d''entrer dans la farce, sinon les barquettes se détrempent par l''intérieur','La tomate va au fond du plat, autour des barquettes, jamais sur les dômes qu''elle empêcherait de croûter']::text[],
    ARRAY['suer','évaporation','farcissage','cuisson au four','gratinage','repos']::text[], ARRAY['Farce à la céréale : un verre de riz basmati (chefsimon) ou 50 g de quinoa (marmiton) cuits avec les lentilles et mélangés à la farce — écartée ici parce qu''elle met le féculent dans le plat et lui ôte son rôle d''assiette','Fromage frais étalé au fond de la barquette, lentilles réparties par-dessus, chapelure, bouillon de légumes versé tout autour et 30 minutes à 220 °C (migusto)','Farce mijotée vingt minutes avec des protéines de soja texturées, du vin blanc, de la sauce soja et une pointe de miso avant d''être enfournée, le reste de farce servant de sauce pour des pâtes (lodeurducafe)','Appareil à l''œuf, à la crème et au parmesan relevé de curry, versé sur les lentilles et le quinoa (marmiton)','Courgettes rondes décalottées et évidées plutôt que des barquettes fendues, avec un chapeau remis pour la cuisson (chefsimon, et le parent)','Farces végétariennes sans légumineuse, relevées dans cinq pages écartées du dossier : brocciu et œuf, ricotta et pignons, semoule fine et sauce tomate, feta marinée et gruyère à la crème','Herbes séchées à la place du cumin : origan, thym ou herbes de Provence (chefsimon, migusto, lodeurducafe)']::text[], ARRAY['lait','gluten']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C dans le plat couvert d''un film, et se réchauffe quinze minutes à 160 °C plutôt qu''au micro-ondes, qui fait suer la courgette et affaisse la barquette. La farce seule se congèle 2 mois à -18 °C et c''est la bonne façon de prendre de l''avance ; les courgettes garnies, en revanche, supportent mal le gel — leur chair, gorgée d''eau, se défait à la décongélation et la barquette devient flasque. C''est ce que dit déjà le parent, aucune page du dossier ne parle de conservation, et une farce de lentilles se comporte ici comme une farce de viande : c''est la courgette qui décide, pas la garniture.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-010'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
