  FROM axis
  CROSS JOIN unnest(ARRAY['Au citron vert plutôt qu''au citron jaune, un fruit entier pour une part (750g)','Avec une tomate fraîche en petits dés fondue avec les oignons, et de la coriandre en poudre ou fraîche au service (750g)','Avec un mélange d''épices yassa du commerce à la place de la moutarde — forme absente du catalogue (notparisienne)','Relevé aux flocons de piment rouge en plus du piment entier, et un tiers de scotch bonnet laissé dans la sauce (eatwithafia)','Tofu passé au gril ou à la poêle sans huile plutôt que frit, pour un plat plus sec (notparisienne)','Servi sur du quinoa au lieu du riz (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
