  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-062', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('bf77f286df1b3f3eae46aa965a82ff2c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":3,"salty":3,"acidic":4,"bitter":1,"umami":2,"heat":2,"pungency":3,"richness":2,"freshness":3,"intensity":4},"dominant_flavors":["oignon compoté","citron","moutarde","piment"],"aroma_families":["agrume","oignon confit","moutarde","piment"],"target_textures":["cubes de tofu croûtés au-dehors et moelleux au-dedans","oignons fondus presque en marmelade","sauce courte et brillante"],"signature_ingredients":["Oignon jaune cru","Tofu ferme","Jus de citron frais","Moutarde de Dijon"],"identity_guardrails":["L''oignon est compoté longuement jusqu''à s''affaisser : sauté dix minutes, il reste croquant et le plat n''est plus un yassa","Le tofu est pressé puis saisi à part avant de retrouver la sauce, sinon il reste blanc et mou","L''acidité du citron doit rester franche à la sortie du feu, c''est elle qui identifie le plat","Le mouillement est un bouillon de légumes, jamais de volaille"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Adobo de tofu', 'adobo de tofu', 'Philippines', 'Philippines',
     'meal', 'tofu braisé vinaigré', 'named_traditional_dish', 'fermented_pungent',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Adobo de tofu', 'Des cubes de tofu dorés puis braisés dans un mélange de vinaigre, de sauce soja, d''ail et de laurier réduit jusqu''à napper — l''adobong tokwa philippin, jumeau végétarien du chicken adobo.', ds.id, 'JUM-063',
    'Myko', 'editorial', 6, 20, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', '4f422e47f9d443684345c4ee5618bd60',
    '{"sweet":2,"salty":4,"acidic":4,"bitter":1,"umami":4,"heat":1,"pungency":4,"richness":2,"freshness":1,"intensity":4}'::jsonb, ARRAY['vinaigre','sauce soja','ail','laurier']::text[],
    ARRAY['vinaigre','soja fermenté','ail grillé','laurier']::text[], ARRAY['cubes de tofu croûtés et gorgés de sauce','sauce courte et sirupeuse','grains de poivre entiers sous la dent']::text[],
    ARRAY['Tofu ferme','Vinaigre blanc','Sauce soja','Ail cru']::text[], ARRAY['Le vinaigre bout deux minutes sans être remué avant tout autre liquide : c''est ce qui fait la rondeur de l''adobo','Le poivre reste en grains entiers, jamais moulu','La sauce doit réduire jusqu''à napper : un adobo noyé n''est plus un adobo','Le tofu est pressé puis doré avant d''entrer dans la sauce, sinon il reste mou et ne prend rien']::text[],
    ARRAY['pressage du tofu','saisie','évaporation du vinaigre','braisage','réduction']::text[], ARRAY['Avec deux pommes de terre rôties au four coupées en demi-lunes, mêlées à la sauce en fin de cuisson (bestofvegan)','Tofu cuit au four ou à l''air chaud vingt-cinq minutes au lieu d''être frit, pour un plat sans friture (healthmylifestyle)','Sauce liée d''une cuillerée de fécule de maïs délayée à l''eau froide et bouillie une minute (healthmylifestyle, ricelifefoodie)','Avec une demi-cuillerée de gingembre frais râpé sauté avec l''ail (ricelifefoodie)','Une cuillerée à café de sauce soja foncée en plus, pour la couleur et le sucré (thefoodietakesflight)','Servi sur du sinangag, le riz frit à l''ail philippin, plutôt que sur du riz nature (thefoodietakesflight)']::text[], ARRAY['soja','gluten']::text[],
    'Se garde 4 jours au réfrigérateur entre 0 et 4 °C dans un récipient fermé, et c''est même un plat qui s''améliore d''un jour sur l''autre : le tofu continue d''absorber la sauce et le vinaigre et le soja, tous deux conservateurs, retardent l''altération — c''est d''ailleurs l''origine du plat, une méthode de conservation avant d''être une recette. Aucune des quatre pages ne chiffre de durée, seulement le fait que le goût gagne au repos ; les 4 jours sont donc notre lecture de ce que fait ce type de plat, et on le dit. Il se congèle 3 mois à -18 °C : la sauce est une réduction sans laitage ni liaison qui ne se déphase pas, et le tofu ressort plus ferme et plus spongieux qu''avant, ce qui dans une sauce nappante est un gain plutôt qu''un défaut. Décongeler une nuit au froid et réchauffer à couvert.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-259'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

