     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 8, 'g', 'required',
     'assaisonnement', false, 14);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 15);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'parmesan affine' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Parmesan affiné', 80, 'g', 'optional',
     'service', true, 16);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Si l''on part de haricots secs, compter deux cent cinquante grammes trempés une nuit puis cuits une heure à l''eau non salée : ils rendront les six cents grammes annoncés, qui sont un poids de haricot cuit et égoutté et non un poids de sachet. En conserve, vider le bocal dans une passoire, rincer à l''eau froide et laisser s''égoutter : la saumure est salée et trouble, et ce que la recette pèse est ce qui sort de la boîte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Tailler oignon, carotte, céleri et pomme de terre en dés d''un centimètre, tous au même calibre. Une soupe qui se mange à la cuillère se juge là : des dés inégaux donnent au même moment des légumes encore fermes et d''autres déjà défaits. Mettre de côté la courgette taillée pareil et les haricots verts coupés en tronçons de deux centimètres, qui n''entreront que bien plus tard.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer la moitié de l''huile d''olive dans un grand faitout, y verser oignon, carotte, céleri et ail écrasé, couvrir et laisser suer une dizaine de minutes à feu doux sans laisser prendre couleur. Sans salaison au fond du récipient, cette base fondue est le seul corps gras aromatique de la soupe : menée trop vite, elle laisse un bouillon plat qu''aucune quantité de légumes ne rattrape ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter les pommes de terre et les tomates écrasées à la main, puis laisser la tomate se défaire cinq minutes à découvert avant tout mouillement. Elle perd là son acidité crue ; noyée tout de suite sous deux litres de liquide, elle la garderait jusqu''au bout.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le bouillon de légumes, amener à petits frémissements, couvrir et compter vingt-cinq minutes. La surface doit à peine trembler — une ébullition franche casse les dés et rend le bouillon trouble. Goûter à ce moment précis : un bouillon de légumes est moins salé et moins gélatineux qu''un bouillon de viande, et c''est maintenant qu''on sait s''il faudra saler à la fin et de combien.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Mettre alors la courgette, les haricots verts et les haricots blancs déjà cuits, puis compter dix minutes. La courgette entrée au départ aurait disparu sans laisser de trace ; les haricots blancs, eux, n''ont qu''à se réchauffer et à prendre le goût du bouillon, car mijotés plus longtemps ils perdent leur peau et troublent le bol.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Jeter les petites pâtes dans la soupe elle-même et les arrêter deux minutes avant le temps indiqué sur le paquet, en goûtant. C''est leur amidon qui épaissit le minestrone, et c''est pour cela qu''on ne les cuit jamais à part. Mais elles boivent encore après le feu coupé : à point dans la marmite, elles auront tout absorbé au moment de servir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Hors du feu, déchirer le basilic à la main dans la soupe, verser le reste d''huile d''olive crue, puis goûter et saler seulement là. Le mouillement n''apporte ici ni le sel ni le corps qu''un bouillon de viande apporterait : ce filet d''huile crue et ces feuilles déchirées sont la finition du plat, pas sa décoration. Servir avec le parmesan râpé à part, pour qui en veut.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-071', 'recipe_family', 'Minestrone végétarien',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-071', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Pesto de persil monté à l''huile et servi à part, à la place du basilic déchiré (chefsimon)','Version croquante : haricots verts, petits pois, radis et jeunes asperges à peine pochés dans le bouillon, avec des spaghettis cassés (chefsimon)','Fenouil et tomates cerises coupées en deux à la place de la tomate mûre, deux brins de menthe et des flocons de piment en finition (biendecheznous)','Trois cent cinquante grammes de macaronis pour quatre, soit près de trois fois le féculent retenu ici (menu-vegetarien) — écarté parce que la soupe devient alors un plat de pâtes en bouillon','Haricots borlotti frais à la place du haricot blanc, avec des blettes et une croûte de parmesan fondue dans le bouillon (mangioquindisono, salepepe)','Navets ronds et navets boule d''or avec les légumes durs (chefsimon, salepepe)','Origan séché et persil haché ajoutés avec le basilic (menu-vegetarien)','Poireau émincé dans la base aromatique (salepepe, et le parent le porte déjà en variante)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-071","variants":["Pesto de persil monté à l''huile et servi à part, à la place du basilic déchiré (chefsimon)","Version croquante : haricots verts, petits pois, radis et jeunes asperges à peine pochés dans le bouillon, avec des spaghettis cassés (chefsimon)","Fenouil et tomates cerises coupées en deux à la place de la tomate mûre, deux brins de menthe et des flocons de piment en finition (biendecheznous)","Trois cent cinquante grammes de macaronis pour quatre, soit près de trois fois le féculent retenu ici (menu-vegetarien) — écarté parce que la soupe devient alors un plat de pâtes en bouillon","Haricots borlotti frais à la place du haricot blanc, avec des blettes et une croûte de parmesan fondue dans le bouillon (mangioquindisono, salepepe)","Navets ronds et navets boule d''or avec les légumes durs (chefsimon, salepepe)","Origan séché et persil haché ajoutés avec le basilic (menu-vegetarien)","Poireau émincé dans la base aromatique (salepepe, et le parent le porte déjà en variante)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-071', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e348a7c8653ee26dfdb10fb0215f70e1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"brothy_umami","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":2,"heat":0,"pungency":1,"richness":2,"freshness":3,"intensity":3},"dominant_flavors":["bouillon de légumes","tomate","haricot blanc","basilic"],"aroma_families":["bouillon","tomate_cuite","oignon_compoté","basilic","céleri"],"target_textures":["légumes_tendres_distincts","bouillon_lié","pâtes_fermes"],"signature_ingredients":["Haricot blanc cuit, égoutté","Petites pâtes sèches","Tomate fraîche mûre","Bouillon de légumes"],"identity_guardrails":["Le bouillon est de légumes et rien d''autre : c''est la seule ligne qui séparait ce plat de son parent, et un cube de volaille le ramènerait dans la lignée carnée sans que rien ne le montre","Aucune salaison, pas même en option — le parent laissait le lardon facultatif, et c''est précisément ce genre d''option qui fait classer un plat végétarien à tort","Un minestrone porte à la fois une légumineuse et un féculent en grain, haricot blanc et petites pâtes : sans eux il n''est plus qu''une soupe de légumes, et ici le haricot est la seule protéine du bol","Les légumes restent en dés distincts sous la cuillère : mixé, le plat devient un velouté et perd la définition qui fait son nom","Les pâtes cuisent dans le bouillon et non à part, leur amidon étant le seul liant de la soupe"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Chorba végétarienne', 'chorba vegetarienne', 'Algérie', 'Algérie',
     'meal', 'soupe complète', 'named_traditional_dish', 'brothy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Chorba végétarienne', 'Soupe algéroise tomatée aux vermicelles, portée par les pois chiches à la place de l''agneau, parfumée à la cannelle, au paprika et à la coriandre fraîche jetée hors du feu.', ds.id, 'JUM-072',
    'Myko', 'editorial', 6, 25, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', '93fd90ce9a57638f882b8b557a0accb8',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":2,"heat":1,"pungency":2,"richness":2,"freshness":3,"intensity":3}'::jsonb, ARRAY['pois chiche','coriandre fraîche','tomate','cannelle']::text[],
    ARRAY['coriandre','cannelle','tomate_cuite','paprika']::text[], ARRAY['bouillon_clair','légumes fondants','vermicelles tendres']::text[],
    ARRAY['Pois chiche cuit, égoutté','Coriandre fraîche','Vermicelle fin sec']::text[], ARRAY['Coriandre fraîche et menthe jetées hors du feu : ce sont elles qui font l''algéroise, et bouillies elles noircissent','Le pois chiche est doublé par rapport au parent parce qu''il est désormais la seule protéine du bol : ramené à la quantité du parent, ce n''est plus le même plat dans l''assiette','Vermicelles trois à quatre minutes seulement — ils continuent de gonfler hors du feu et boivent tout le bouillon','Le concentré de tomate se fait revenir avant d''être mouillé, sans quoi il garde son goût de boîte, que rien ne masque plus ici','Les légumes restent en morceaux : mixée, comme le font trois pages du dossier, la chorba devient un velouté et perd sa mâche']::text[],
    ARRAY['suer','réduction','mijotage','cuisson séquencée','infusion des herbes']::text[], ARRAY['Chorba frik : 80 g de blé vert concassé pour six à la place des vermicelles (amourdecuisine) — c''est une chorba frik, que le parent porte déjà en variante','Soupe mixée : retirer les légumes cuits, les passer au moulin et les remettre dans la marmite avant les vermicelles, en gardant les pois chiches entiers (mesinspirations, marciatack, ptitchef) — écartée parce que le parent, et cette recette avec lui, tient à des légumes reconnaissables sous la cuillère','Curcuma et cumin à la place du paprika et de la cannelle, avec du coulis de tomate en plus des tomates concassées (chefsimon)','Persil plat à la place de la coriandre fraîche (ptitchef)','Piment frais entier cuit dans le bouillon puis retiré au moment de servir (amourdecuisine)','Menthe séchée émiettée au service à la place de la menthe fraîche ciselée (chefsimon, mesinspirations)','Quartier de citron pressé dans l''assiette au service (amourdecuisine, chefsimon, marciatack)','Pois chiches secs trempés la veille et cuits dans le bouillon lui-même, ce qui allonge la cuisson d''une heure mais donne un bouillon plus épais (mesinspirations, amourdecuisine)']::text[], ARRAY['gluten','céleri']::text[],
    'Se garde 3 jours au réfrigérateur. Les vermicelles gonflent en refroidissant et la soupe devient épaisse comme une purée : rallonger d''un verre d''eau au réchauffage, à feu doux. Pour prendre de l''avance, s''arrêter à la fin de la cuisson des légumes — cette base se garde 4 jours au froid et se congèle 3 mois à -18 °C, et il ne reste alors que quatre minutes de vermicelles et cinq minutes d''infusion. Congeler la soupe finie n''a pas d''intérêt : le vermicelle en ressort collé. Aucune page du dossier ne parle de conservation ; ces durées valent pour toute soupe portant des pâtes fines, et ce sont celles que le parent donne déjà pour une structure identique.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'VAR-022'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
