  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Égoutter le tofu, l''éponger et le détailler en tranches d''un centimètre d''épaisseur. Épaisseur régulière et non dés minuscules : chaque face doit pouvoir dorer à plat, et un dé de tofu n''a que des arêtes qui cassent quand on le retourne.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Rouler chaque tranche dans la fécule et tapoter pour n''en garder qu''un voile. C''est ce voile qui remplace la peau du poulet de la recette d''origine : il forme à la cuisson une pellicule qui retient la sauce au lieu de la laisser glisser, et sans lui le tofu ressort pâle et la sauce reste au fond de la casserole.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile de colza dans une grande poêle antiadhésive à feu moyen-vif et dorer les tranches deux à trois minutes par face, en deux fournées plutôt qu''en une. Une poêle chargée retombe en température, la fécule boit alors l''huile au lieu de sécher, et l''on obtient un tofu gras et mou. Réserver sur une grille.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Vider l''huile de friture de la poêle, l''essuyer et y verser l''huile de sésame grillé sur feu doux. Cette huile ne supporte pas la chaleur vive — c''est une huile de parfum, pas une huile de cuisson — et elle devient amère si on la fume, ce qui coûterait au plat un de ses trois piliers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faire blondir doucement dans le sésame les gousses d''ail entières épluchées et le gingembre en fines lamelles, deux à trois minutes, jusqu''à ce que les gousses dorent sur leurs faces. L''ail entier fond et devient sucré ; haché il brûlerait dans le même temps et donnerait un fond âcre à toute la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser la sauce soja légère, le vin de riz et le sucre candi, ajouter le piment fendu et six cuillerées à soupe d''eau, et laisser bouillonner deux minutes pour dissoudre le sucre. L''eau n''est pas une quatrième tasse : elle donne à la réduction le temps de se faire sans que le soja ne devienne salant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Remettre le tofu doré dans la poêle, le retourner plusieurs fois dans la sauce et laisser réduire huit à dix minutes à découvert, à feu moyen, jusqu''à ce que la sauce nappe et brille. C''est le glaçage qui fait le plat : tant qu''il reste du liquide clair au fond, ce n''est pas fini, et si la sauce colle avant que le tofu ne soit enrobé, ajouter deux cuillerées d''eau plutôt que de baisser trop tôt.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Couper le feu, jeter le basilic thaï en une fois et remuer trois ou quatre fois sous le couvercle avant de servir aussitôt. Le basilic doit tomber dans une casserole hors du feu : cuit, il noircit et perd en trente secondes l''arôme anisé qui est la signature du plat, et c''est la faute la plus fréquente sur un trois-tasses.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-092', 'recipe_family', 'San bei doufu',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-092', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
