  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les pois chiches, les égoutter et les rouler longuement dans un torchon jusqu''à ce qu''ils soient parfaitement secs, en ôtant au passage les peaux qui se détachent. C''est l''étape qui décide de tout le reste : un pois chiche humide cuit à la vapeur de sa propre eau au lieu de rôtir, et il ressort mou après une heure de four comme après quinze minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Les étaler sur une plaque, les enrober de deux cuillerées à soupe d''huile prélevées sur le total, du paprika fumé et d''une pincée de sel, et les rôtir 30 minutes à 200 °C en secouant la plaque toutes les dix minutes. Ils doivent sonner sec sous la cuillère et non rester tendres au centre : c''est ce croquant qui remplace, dans l''assiette, la mâche du poulet grillé de la recette d''origine.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Couper le pain en cubes de deux centimètres, croûte comprise, les arroser d''une cuillerée d''huile et les faire dorer dix minutes au four à côté des pois chiches. Les frotter chauds avec la moitié d''une gousse d''ail crue : l''ail fond au contact du pain brûlant et parfume sans jamais brûler, ce qu''il ferait si on l''ajoutait avant la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Monter la sauce comme une mayonnaise : les deux jaunes d''œuf, la moutarde, le reste de l''ail réduit en purée, le sel et le poivre dans un bol, fouettés vingt secondes, puis l''huile restante versée goutte à goutte au début et en filet ensuite, sans cesser de fouetter. Elle doit devenir ferme et pâle avant qu''on la détende.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'La détendre avec le jus de citron et la moitié du parmesan finement râpé. Elle doit napper la cuillère en coulant lentement : trop épaisse, elle colle en paquets sur les feuilles au lieu de les enrober, et l''allonger d''une cuillerée d''eau froide vaut mieux que d''ajouter du citron, qui déséquilibrerait l''acidité.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laver et essorer soigneusement la romaine, puis la déchirer à la main en larges morceaux plutôt que de la couper au couteau — la lame oxyde les nervures, qui brunissent en une heure. L''essorage compte autant : une feuille mouillée repousse la sauce, qui glisse au fond du saladier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Assembler au dernier moment : verser les deux tiers de la sauce sur la salade, mélanger longuement pour enrober chaque feuille, puis ajouter les croûtons, les pois chiches rôtis et le reste de sauce. Finir par les copeaux de parmesan taillés à l''économe. Montée à l''avance, cette César a des croûtons mous et des pois chiches ramollis en vingt minutes — les pois chiches encore plus vite que le pain, parce que leur croûte est plus fine.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-093', 'recipe_family', 'Salade César aux pois chiches rôtis',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-093', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
