  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Sauce sur une mayonnaise du commerce allongée de yaourt grec, un tiers de tasse de chacun (planbouffe)','Sauce végane à la crème de soja et aux câpres écrasées, sans jaune d''œuf, avec du parmesan végane (patateetcornichon)','Vinaigre de vin rouge à la place du jus de citron, deux cuillerées à soupe (soscuisine)','Cinq gouttes de Tabasco dans la sauce (soscuisine)','Carottes râpées ou en spirales, trois moyennes, mélangées à la laitue (planbouffe)','Tranches d''avocat ajoutées à la dernière minute (planbouffe)','Zeste d''un citron sur les pois chiches avant rôtissage (planbouffe)','Câpres, une cuillerée à soupe écrasée à la fourchette dans la sauce (patateetcornichon)','Sans croûtons de pain, les pois chiches rôtis tenant seuls le rôle du croquant (planbouffe)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-093","variants":["Sauce sur une mayonnaise du commerce allongée de yaourt grec, un tiers de tasse de chacun (planbouffe)","Sauce végane à la crème de soja et aux câpres écrasées, sans jaune d''œuf, avec du parmesan végane (patateetcornichon)","Vinaigre de vin rouge à la place du jus de citron, deux cuillerées à soupe (soscuisine)","Cinq gouttes de Tabasco dans la sauce (soscuisine)","Carottes râpées ou en spirales, trois moyennes, mélangées à la laitue (planbouffe)","Tranches d''avocat ajoutées à la dernière minute (planbouffe)","Zeste d''un citron sur les pois chiches avant rôtissage (planbouffe)","Câpres, une cuillerée à soupe écrasée à la fourchette dans la sauce (patateetcornichon)","Sans croûtons de pain, les pois chiches rôtis tenant seuls le rôle du croquant (planbouffe)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-093', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0735d0a95cfa9b2c309f7423a56dc0e2'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":4,"acidic":3,"bitter":1,"umami":3,"heat":1,"pungency":3,"richness":5,"freshness":3,"intensity":4},"dominant_flavors":["parmesan","moutarde","citron","paprika fumé"],"aroma_families":["fromage_affiné","moutarde","agrume","fumé","grillé"],"target_textures":["feuilles croquantes","pois chiches croustillants","pain croustillant","crémeux"],"signature_ingredients":["Pois chiche cuit, égoutté","Laitue fraîche","Parmesan affiné","Jaune d''œuf cru"],"identity_guardrails":["La sauce se monte au jaune d''œuf comme une mayonnaise : une vinaigrette n''en est pas une","Les pois chiches sont séchés puis rôtis jusqu''au croquant — versés mous, ils ne remplacent rien","Romaine et non mesclun : c''est la nervure croquante qui tient la sauce","On assemble au dernier moment, sinon feuilles, croûtons et pois chiches s''affaissent ensemble","Aucun anchois ni sauce Worcestershire d''anchois : c''est ce qui fait de cette César un jumeau végétarien"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Aubergines panées', 'aubergines panees', 'Italie', 'Italie',
     'meal', 'légume pané', 'named_traditional_dish', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Aubergines panées', 'Tranches d''aubergine dégorgées au gros sel, panées à l''anglaise dans une chapelure au parmesan et dorées à la poêle, servies chaudes', ds.id, 'JUM-094',
    'Myko', 'editorial', 4, 25, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f349264c000d0505c4a45c0af2ab102d',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":0,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['aubergine fondante','parmesan','pain grillé']::text[],
    ARRAY['fromage affiné','pain grillé','huile d''olive','légume rôti']::text[], ARRAY['croûte croustillante','cœur fondant','contraste_fort']::text[],
    ARRAY['Aubergine fraîche','Chapelure de blé','Parmesan affiné']::text[], ARRAY['Les tranches se dégorgent au gros sel puis se rincent : sans cela l''eau de l''aubergine décolle la panure dans la poêle','Panure à l''anglaise en trois temps, farine comprise — sans farine la croûte se détache et le plat n''existe plus','Une tranche d''un demi-centimètre : plus épaisse elle reste crue au centre, plus fine elle s''effondre en pâte','Panées et frites, jamais gratinées à la tomate — ce serait une parmigiana, qui est un autre plat du corpus','Le sel entre dans la chapelure et non sur le légume, qui sort déjà salé du dégorgeage']::text[],
    ARRAY['dégorgeage au gros sel','panure à l''anglaise','repos','friture à la poêle']::text[], ARRAY['Double panure — chapelure, œuf, chapelure de nouveau — pour une croûte plus épaisse (misya, tortelliniandco)','Au four, 20 minutes à 190 °C, retournées à mi-cuisson et arrosées d''huile d''olive sur chaque face (tortelliniandco, marmiton)','À la friteuse à air, 15 minutes à 190 °C (marmiton)','Panure au persil haché et à une demi-gousse d''ail (ilcuoreinpentola, marmiton)','Œufs battus avec cinq cuillerées à soupe de lait à la place des œufs seuls (marmiton)','Sans parmesan dans la chapelure (giallozafferano, tortelliniandco)','Panure enrichie de cinquante grammes de poudre d''amande (chefsimon)','Courgettes taillées de la même façon et panées avec les aubergines, moitié-moitié (marmiton)','Servies avec une sauce tomate chaude et de la semoule (marmiton)','Origan séché dans la chapelure, une cuillerée à café (750g)']::text[], ARRAY['gluten','œuf','lait']::text[],
    'Se mangent dans les minutes qui suivent la poêle : la panure ramollit encore plus vite que sur une escalope, l''aubergine continuant de rendre de la vapeur par en dessous. Une page italienne le dit en toutes lettres — gardées couvertes et au chaud, elles restent bonnes mais perdent leur croûte. Les restes se gardent 2 jours au réfrigérateur, à plat et jamais empilés, et se réchauffent 8 minutes au four à 180 °C posés sur une grille ; le micro-ondes est à proscrire, il rend la croûte élastique. Ne se congèlent pas cuites, pour une raison propre au légume et non à la panure : l''eau que l''aubergine garde en cellules gèle en cristaux qui crèvent sa chair, et la tranche ressort en purée sous une croûte intacte. Panées crues, elles se congèlent en revanche 2 mois séparées par du papier cuisson et se cuisent sans décongélation en allongeant de trois minutes par face — c''est ce que fait la fiche parente avec ses escalopes, et la physique est ici la même puisque c''est la panure qui tient le gel.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'VAR-003'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
