  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Laver les aubergines, ôter le pédoncule et les couper en tranches d''un demi-centimètre d''épaisseur régulière, dans le sens de la longueur ou de la largeur selon la forme du légume. Écarter les deux tranches extérieures, presque entièrement peau : elles ne cuisent pas comme les autres et restent coriaces sous la panure.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ranger les tranches en couches dans une passoire en salant chaque étage de gros sel, poser une assiette et un poids dessus, et laisser dégorger une heure. C''est ce qui remplace l''aplatissement de l''escalope dans la recette d''origine : l''aubergine est une éponge, et l''eau qu''elle ne rend pas maintenant, elle la rendra sous la panure, qu''elle décollera.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Rincer abondamment les tranches à l''eau froide pour ôter tout le sel, puis les éponger entre deux torchons en pressant. Ne pas rincer laisserait un plat immangeable de sel ; ne pas sécher rendrait la farine collante et la panure irrégulière.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Préparer trois assiettes creuses : la farine dans la première, les œufs battus à la fourchette avec le poivre dans la deuxième, la chapelure mélangée au parmesan finement râpé et au sel fin dans la troisième. Le sel va dans la chapelure et non sur l''aubergine, à l''inverse de ce que demande une viande : les tranches sortent du dégorgeage déjà légèrement salées, et les resaler donnerait un plat immangeable.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Passer chaque tranche dans la farine en tapotant pour ôter l''excédent, puis dans l''œuf, puis dans le mélange chapelure-parmesan en appuyant franchement de la paume. La farine sèche la surface pour que l''œuf s''y accroche ; sans elle la panure se décolle en cuisant et il reste une tranche nue au milieu d''une croûte flottante.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser les tranches panées reposer un quart d''heure au frais sur une grille. L''humidité de l''œuf gélifie la chapelure et la soude au légume ; une tranche cuite dans la foulée perd la moitié de sa croûte dans la poêle, et l''aubergine tient encore moins la panure qu''une escalope, faute de fibres pour l''accrocher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Chauffer l''huile d''olive dans une grande poêle à feu moyen et cuire les tranches en deux fournées, trois à quatre minutes de chaque côté, sans les entasser ni les déplacer pendant la première moitié du temps. La poêle chargée refroidit, la panure boit alors le gras au lieu de le repousser, et l''aubergine ressort grasse et molle. Ajouter un filet d''huile entre les fournées, jamais pendant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Égoutter deux minutes sur une grille — jamais sur du papier absorbant, qui retient la vapeur sous la tranche et ramollit le dessous — et servir aussitôt, chaud ou tiède. C''est un plat qui ne supporte pas l''attente : la vapeur que l''aubergine continue de rendre traverse la croûte de l''intérieur.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-094', 'recipe_family', 'Aubergines panées',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-094', 'missing_required_count', v_missing), 'open');
  END IF;

