    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Double panure — chapelure, œuf, chapelure de nouveau — pour une croûte plus épaisse (misya, tortelliniandco)','Au four, 20 minutes à 190 °C, retournées à mi-cuisson et arrosées d''huile d''olive sur chaque face (tortelliniandco, marmiton)','À la friteuse à air, 15 minutes à 190 °C (marmiton)','Panure au persil haché et à une demi-gousse d''ail (ilcuoreinpentola, marmiton)','Œufs battus avec cinq cuillerées à soupe de lait à la place des œufs seuls (marmiton)','Sans parmesan dans la chapelure (giallozafferano, tortelliniandco)','Panure enrichie de cinquante grammes de poudre d''amande (chefsimon)','Courgettes taillées de la même façon et panées avec les aubergines, moitié-moitié (marmiton)','Servies avec une sauce tomate chaude et de la semoule (marmiton)','Origan séché dans la chapelure, une cuillerée à café (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-094","variants":["Double panure — chapelure, œuf, chapelure de nouveau — pour une croûte plus épaisse (misya, tortelliniandco)","Au four, 20 minutes à 190 °C, retournées à mi-cuisson et arrosées d''huile d''olive sur chaque face (tortelliniandco, marmiton)","À la friteuse à air, 15 minutes à 190 °C (marmiton)","Panure au persil haché et à une demi-gousse d''ail (ilcuoreinpentola, marmiton)","Œufs battus avec cinq cuillerées à soupe de lait à la place des œufs seuls (marmiton)","Sans parmesan dans la chapelure (giallozafferano, tortelliniandco)","Panure enrichie de cinquante grammes de poudre d''amande (chefsimon)","Courgettes taillées de la même façon et panées avec les aubergines, moitié-moitié (marmiton)","Servies avec une sauce tomate chaude et de la semoule (marmiton)","Origan séché dans la chapelure, une cuillerée à café (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-094', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f349264c000d0505c4a45c0af2ab102d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":0,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["aubergine fondante","parmesan","pain grillé"],"aroma_families":["fromage affiné","pain grillé","huile d''olive","légume rôti"],"target_textures":["croûte croustillante","cœur fondant","contraste_fort"],"signature_ingredients":["Aubergine fraîche","Chapelure de blé","Parmesan affiné"],"identity_guardrails":["Les tranches se dégorgent au gros sel puis se rincent : sans cela l''eau de l''aubergine décolle la panure dans la poêle","Panure à l''anglaise en trois temps, farine comprise — sans farine la croûte se détache et le plat n''existe plus","Une tranche d''un demi-centimètre : plus épaisse elle reste crue au centre, plus fine elle s''effondre en pâte","Panées et frites, jamais gratinées à la tomate — ce serait une parmigiana, qui est un autre plat du corpus","Le sel entre dans la chapelure et non sur le légume, qui sort déjà salé du dégorgeage"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Empanadas aux lentilles', 'empanadas aux lentilles', 'Argentine', 'Argentine',
     'meal', 'chaussons', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Empanadas aux lentilles', 'Chaussons argentins de pâte à l''huile d''olive, farcis d''un sofrito d''oignon au cumin et au paprika lié de lentilles brunes fondantes, avec des olives vertes, et cuits au four', ds.id, 'JUM-095',
    'Myko', 'editorial', 6, 60, 30, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'c231dacb5f52a683a9e6754d8b521d1e',
    '{"sweet":2,"salty":3,"acidic":1,"bitter":1,"umami":3,"heat":1,"pungency":2,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['cumin','paprika','oignon compoté','olive']::text[],
    ARRAY['cumin','paprika','oignon_compoté','olive','pâte_cuite']::text[], ARRAY['pâte_croustillante','farce_fondante_et_morceaux']::text[],
    ARRAY['Lentille brune sèche, crue','Farine de blé T55','Oignon jaune cru','Olive verte dénoyautée']::text[], ARRAY['La graisse de la pâte est végétale : le saindoux de la fiche parente est précisément ce qu''un jumeau végétarien ne peut pas garder','Les lentilles se cuisent un peu trop, jusqu''à se tenir à la cuillère — fermes, elles percent la pâte au façonnage','La farce entre froide dans les disques, jamais tiède','Sofrito d''oignon au cumin et au paprika, pas de sauce tomate : c''est ce qui sépare l''empanada argentine de toutes les autres','Repulgue ou bord écrasé à la fourchette, et pas de bulle d''air enfermée']::text[],
    ARRAY['trempage','pâte à l''huile','sofrito','refroidissement de la farce','repulgue','cuisson au four']::text[], ARRAY['Pommes de terre bouillies en petits dés dans la farce, quatre pour douze empanadas (lanacion)','Farine complète à la place de la farine blanche (lanacion)','Trois sortes d''oignons — cébette, oignon blanc, oignon rouge — au lieu du seul oignon jaune (nomadasgourmet)','Raisins secs, une cuillerée à soupe pour douze, à ajouter avec les olives (nomadasgourmet)','Dorure à l''eau colorée au paprika, deux cuillerées d''eau pour un quart de cuillerée à café (nomadasgourmet)','Graines de sésame et deux feuilles de basilic frais dans la farce (receta-vegetariana)','Farine de maïs à la place de la farine de blé pour la pâte (receta-vegetariana)','Chaussons frits plutôt que cuits au four (receta-vegetariana)','Cuisson à four très chaud, 230 °C pendant 15 minutes (nomadasgourmet)']::text[], ARRAY['gluten']::text[],
    'Se gardent 3 jours au réfrigérateur dans une boîte, et se réchauffent 10 minutes au four à 180 °C, jamais au micro-ondes qui détrempe la pâte. Aucune des trois pages ne parle de congélation ; ce que fait ce type de chausson est en revanche connu et vaut d''être écrit comme une déduction et non comme une consigne des sources : une empanada crue, farcie et fermée, se congèle 3 mois à plat sur une plaque puis en sac, et se cuit sans décongélation en ajoutant cinq à huit minutes de four — c''est de loin le meilleur usage, la pâte crue n''ayant encore rien perdu. Cuites, elles se congèlent aussi 2 mois mais ressortent avec une pâte plus sableuse. La farce seule se garde 3 jours au froid et gagne au deuxième jour, le cumin ayant fini de se répartir : c''est elle qu''il vaut mieux préparer d''avance quand on veut étaler le travail sur deux soirs.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-280'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'farine de ble t55' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Farine de blé T55', 480, 'g', 'required',
     'pâte', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'huile d olive vierge extra' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Huile d''olive vierge extra', 60, 'ml', 'required',
     'pâte', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'lentille brune seche crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
