  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Mettre les lentilles à tremper dans un grand volume d''eau froide pendant que le reste s''organise, une heure suffit, puis les cuire vingt-cinq à trente minutes à l''eau frémissante NON salée. Les cuire un peu au-delà du point où on les servirait telles quelles : une lentille encore ferme roule sous la pâte au moment de fermer le chausson et perce le pli, là où une lentille fondante se tient à la cuillère comme le fait un haché.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Pendant ce temps, préparer la pâte : mélanger la farine et 5 g de sel, verser 40 ml de l''huile d''olive puis environ 220 ml d''eau tiède en travaillant à la main jusqu''à obtenir une boule lisse qui ne colle plus. Couvrir d''un linge humide et laisser reposer une demi-heure. Le repos n''est pas du confort : il détend le gluten, sans quoi les disques se rétractent au rouleau et se déchirent au façonnage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire suer l''oignon finement haché et le poivron en petits dés dans les 20 ml d''huile restants, à feu doux, dix à douze minutes, jusqu''à ce que l''oignon soit translucide et sucré. Sans viande pour donner du corps, cette base est le seul fondement de la farce : conduite à feu vif elle brunit sans fondre, et la farce reste un mélange de lentilles et d''oignon cru au lieu d''un tout.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter l''ail haché, le cumin et le paprika, et remuer trente à quarante secondes dans le gras chaud avant tout ajout de lentilles. Les épices moulues sont solubles dans la matière grasse et non dans l''eau : versées sur des lentilles humides, elles restent en suspension et donnent un goût poudreux au lieu d''un fond aromatique.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter les lentilles égouttées, les olives en quartiers, le sel restant, le poivre et, si l''on en met, les raisins secs. Cuire cinq minutes à feu moyen en écrasant une cuillerée de lentilles contre la paroi, jusqu''à ce qu''il n''y ait plus une goutte de liquide libre. Une farce humide traverse la pâte crue et fait éclater les chaussons au four ; l''écrasement partiel libère l''amidon qui lie la farce à froid.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler la farce sur une plaque et la laisser refroidir complètement, au réfrigérateur si besoin. Une farce tiède fait fondre le gras de la pâte au contact et ramollit le disque avant même qu''on l''ait replié ; c''est la même exigence que dans l''empanada de bœuf, et pour la même raison.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Diviser la pâte en douze boules, les abaisser en disques de quinze centimètres, poser une bonne cuillerée à soupe de farce au centre de chacun, humecter le bord d''un doigt trempé dans l''eau, replier en demi-lune et souder en chassant l''air. Fermer sur une bulle d''air, c''est cuire un ballon qui s''ouvrira en s''étirant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Sceller le bord par le repulgue — pincer un coin, le rabattre sur lui-même et répéter le long du chausson — ou, à défaut, écraser franchement le bord à la fourchette. Ce n''est pas un décor : c''est ce qui empêche la vapeur de la farce de forcer la soudure pendant la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Ranger les chaussons sur une plaque huilée, les badigeonner d''un peu d''huile ou d''eau colorée au paprika, et cuire 15 à 20 minutes à 200 °C jusqu''à ce qu''ils soient dorés. Il n''y a pas d''œuf battu dans cette version, la dorure vient donc du gras et de la couleur du paprika ; surveiller à partir de la dixième minute, une pâte à l''huile brunit plus vite qu''une pâte au saindoux.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-095', 'recipe_family', 'Empanadas aux lentilles',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-095', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Pommes de terre bouillies en petits dés dans la farce, quatre pour douze empanadas (lanacion)','Farine complète à la place de la farine blanche (lanacion)','Trois sortes d''oignons — cébette, oignon blanc, oignon rouge — au lieu du seul oignon jaune (nomadasgourmet)','Raisins secs, une cuillerée à soupe pour douze, à ajouter avec les olives (nomadasgourmet)','Dorure à l''eau colorée au paprika, deux cuillerées d''eau pour un quart de cuillerée à café (nomadasgourmet)','Graines de sésame et deux feuilles de basilic frais dans la farce (receta-vegetariana)','Farine de maïs à la place de la farine de blé pour la pâte (receta-vegetariana)','Chaussons frits plutôt que cuits au four (receta-vegetariana)','Cuisson à four très chaud, 230 °C pendant 15 minutes (nomadasgourmet)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-095","variants":["Pommes de terre bouillies en petits dés dans la farce, quatre pour douze empanadas (lanacion)","Farine complète à la place de la farine blanche (lanacion)","Trois sortes d''oignons — cébette, oignon blanc, oignon rouge — au lieu du seul oignon jaune (nomadasgourmet)","Raisins secs, une cuillerée à soupe pour douze, à ajouter avec les olives (nomadasgourmet)","Dorure à l''eau colorée au paprika, deux cuillerées d''eau pour un quart de cuillerée à café (nomadasgourmet)","Graines de sésame et deux feuilles de basilic frais dans la farce (receta-vegetariana)","Farine de maïs à la place de la farine de blé pour la pâte (receta-vegetariana)","Chaussons frits plutôt que cuits au four (receta-vegetariana)","Cuisson à four très chaud, 230 °C pendant 15 minutes (nomadasgourmet)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-095', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c231dacb5f52a683a9e6754d8b521d1e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":1,"bitter":1,"umami":3,"heat":1,"pungency":2,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["cumin","paprika","oignon compoté","olive"],"aroma_families":["cumin","paprika","oignon_compoté","olive","pâte_cuite"],"target_textures":["pâte_croustillante","farce_fondante_et_morceaux"],"signature_ingredients":["Lentille brune sèche, crue","Farine de blé T55","Oignon jaune cru","Olive verte dénoyautée"],"identity_guardrails":["La graisse de la pâte est végétale : le saindoux de la fiche parente est précisément ce qu''un jumeau végétarien ne peut pas garder","Les lentilles se cuisent un peu trop, jusqu''à se tenir à la cuillère — fermes, elles percent la pâte au façonnage","La farce entre froide dans les disques, jamais tiède","Sofrito d''oignon au cumin et au paprika, pas de sauce tomate : c''est ce qui sépare l''empanada argentine de toutes les autres","Repulgue ou bord écrasé à la fourchette, et pas de bulle d''air enfermée"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Arancini aux champignons', 'arancini aux champignons', 'Italie', 'Italie',
     'meal', 'croquettes de riz', 'named_traditional_dish', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Arancini aux champignons', 'La version sans viande de l''arancino sicilien : riz safrané cuit par absorption, champignons de Paris poêlés à sec et petits pois, cœur de mozzarella, panure et friture.', ds.id, 'JUM-101',
    'Myko', 'editorial', 8, 60, 60, 'difficile',
    NULL, NULL,
    'B', 'candidate', 'd22b1b3e02730c4194ff978c44cd0496',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":1,"pungency":2,"richness":4,"freshness":2,"intensity":4}'::jsonb, ARRAY['champignon rôti','croustillant','safran']::text[],
    ARRAY['champignon','ail','safran','persil','mozzarella','riz_frit']::text[], ARRAY['croûte_croustillante','riz_moelleux','cœur_fondant']::text[],
    ARRAY['Riz arborio cru','Champignon de Paris frais','Mozzarella','Safran']::text[], ARRAY['Les champignons se poêlent jusqu''à ce que leur eau soit partie : humides, ils détrempent le riz et la boule s''ouvre dans l''huile','Le riz se cuit par absorption et refroidit à découvert au moins deux heures — c''est ce qui le rend moulable, et rien ne remplace ce temps','Le cœur de mozzarella et la panure font l''arancino : sans farce centrale, c''est une boulette de riz','Le bouillon est de légumes, jamais de volaille — c''est ce qui distingue ce jumeau de sa base carnée','Le safran teint le riz du parent et reste : un arancino blanc n''est plus sicilien']::text[],
    ARRAY['sauté','cuisson du riz','refroidissement','façonnage','panure','friture']::text[], ARRAY['Riz monté en risotto — nacré à l''huile, mouillé louche à louche — plutôt que cuit par absorption (sugarsaltmagic, nodashofgluten, ricettechepassione, saq)','Vin blanc sec pour déglacer avant le bouillon, un demi-verre pour 500 g de riz (nodashofgluten, ricettechepassione, lepassionidima, saq)','Cèpes séchés réhydratés, dont l''eau de trempage filtrée rejoint le bouillon, 5 g pour 145 g de riz (sugarsaltmagic) ou 125 ml de bolets séchés (saq)','Farce liée à une béchamel aux champignons plutôt que champignons mêlés au riz, 150 g de béchamel pour 500 g de riz (ilcaldosaporedelsud, tuorlorosso)','Pâte à frire de farine et d''eau à la place de l''œuf pour la panure (ilcaldosaporedelsud, ricettechepassione)','Double friture, quatre à cinq minutes deux fois, pour une croûte plus résistante (ilcaldosaporedelsud)','Servi avec une sauce tomate rôtie au thym et au vinaigre balsamique (simply-delicious-food), une marinara (nodashofgluten) ou une sauce tomate épicée (saq)','Cœur de caciotta, de provola ou d''emmental à la place de la mozzarella, que deux pages jugent trop peu goûteuse (ilcaldosaporedelsud)','Mélange de champignons — pleurotes, cardoncelli, portobello — plutôt que champignons de Paris seuls (lepassionidima, ilcaldosaporedelsud)']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se gardent 2 jours au réfrigérateur en boîte fermée et se réchauffent dix minutes à 180 °C — jamais au micro-ondes, qui ramollit la panure sans réchauffer le cœur. Sur la congélation, les deux pages du dossier qui en parlent se contredisent, et chacune a raison à sa manière : l''une déconseille de congeler l''arancino, cru ou frit, parce que le riz en ressort en bouillie ; l''autre congèle les boules panées CRUES et les plonge encore gelées dans l''huile. C''est cette seconde lecture qu''on retient — 2 mois crus et panés, à frire sans décongeler, en comptant deux minutes de plus — parce qu''un riz qui n''est pas encore passé par l''huile n''a pas de croûte à perdre. Frit, l''arancino ne se congèle pas.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-097'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'riz arborio cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Riz arborio cru', 500, 'g', 'required',
     'base', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
