  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les lentilles à l''eau froide dans une passoire, puis les faire glisser en couche mince sur la main pour repérer un gravillon — il s''en cache un dans un paquet sur trois, et il se signale toujours sous la dent de quelqu''un. Pas de trempage : la peau s''attendrit, les grains s''ouvrent au mijotage, et tout ce plat repose sur des grains entiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Peler et détailler carotte, oignon et échalote au format d''un grain de lentille, pour que rien ne se mange à part. Prévoir à l''achat 210 g de carottes et 170 g d''oignon, les épluchures emportant la différence ; l''ail se pèse gousses nues, soit trois à quatre gousses. Couper enfin le tofu fumé en dés d''un centimètre et les sécher dans un linge — humide, il colle au fond de la cocotte et se déchire au premier retournement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer la moitié de l''huile dans une cocotte à fond épais et y colorer les dés de tofu à feu moyen-vif, cinq à six minutes, en ne les retournant que lorsqu''ils se détachent seuls. C''est le geste qui remplace le lard rendant sa graisse : le tofu n''en rend aucune, il faut la lui donner, et c''est cette croûte-là qui portera le fumé dans le jus. Les débarrasser dans une assiette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre la cocotte à feu moyen avec le reste de l''huile et y laisser tomber carotte, oignon et échalote une dizaine de minutes, sans jamais les laisser prendre couleur : on cherche ici le fondant, la coloration étant déjà venue avec le tofu. Jeter l''ail haché à la toute fin, trente secondes, et pas avant — il brûle deux fois plus vite que l''oignon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser les lentilles égouttées et les tourner une minute dans les légumes gras : elles se laquent et prennent le fond de cocotte avant de rencontrer le moindre liquide. Mouiller alors d''un litre d''eau froide, deux doigts au-dessus des grains, et glisser thym, laurier et clous de girofle. Amener à ébullition, redescendre au frémissement, couvrir aux trois quarts, compter trente-cinq à quarante minutes. Toujours rien de salé à ce stade.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre les dés de tofu dix minutes avant la fin seulement. Plus tôt, ils boivent le jus et redeviennent mous : c''est le même calcul que pour les lardons du parent, à ceci près qu''un lardon avait encore du gras à donner au bouillon, quand le tofu n''a plus rien à échanger une fois doré.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Prélever un grain et le goûter : il doit se défaire sous la dent sans perdre sa peau. Retirer alors le laurier et les girofles, saler, poivrer, et verser la crème pour qui veut un jus rond, en laissant frémir trois minutes qu''elle s''y lie. Persil ciselé au dernier moment, hors du feu.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-112', 'recipe_family', 'Lentilles au tofu fumé',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-112', 'missing_required_count', v_missing), 'open');
  END IF;

