  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler le tofu fumé en dés de moins d''un centimètre. La taille compte plus qu''il n''y paraît : le guanciale du parent fond et se dissout à moitié dans la sauce, le tofu ne fond pas du tout, et des dés trop gros donneraient des morceaux qu''on mange à part au lieu d''un condiment réparti dans les pâtes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Émincer l''oignon très finement et le laisser fondre dans l''huile d''olive, deux à trois minutes à feu moyen. Il doit devenir translucide sans prendre couleur : doré, il amerait pendant les vingt minutes de sauce qui suivent, et l''amertume est la seule faute qu''une amatriciana ne pardonne pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Monter le feu, ajouter les dés de tofu et les laisser colorer quatre à cinq minutes en ne remuant que deux ou trois fois, jusqu''à ce que leurs arêtes croustillent. C''est ici que se joue le plat : le guanciale rendait sa graisse et laissait des bords croquants, le tofu ne rend rien et n''obtient ses bords que d''un contact franc avec la poêle. Déglacer du vin blanc si l''on en met et laisser s''évaporer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Écraser les tomates pelées à la fourchette et les verser avec leur jus, ajouter le piment émietté, et laisser réduire vingt à vingt-cinq minutes à découvert et à feu doux, jusqu''à ce que la sauce nappe la cuillère. Goûter avant de saler : le tofu fumé et le pecorino apportent déjà l''essentiel du sel.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Cuire les bucatini dans un grand volume d''eau salée, une minute de moins que le temps du paquet, et prélever une louche d''eau de cuisson avant d''égoutter. Cette eau chargée d''amidon est ce qui liera la sauce à la place du gras du guanciale.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Jeter les pâtes égouttées dans la poêle avec un fond d''eau de cuisson et les faire sauter une minute pour finir de les cuire dans la sauce. Couper le feu, attendre quelques secondes, puis ajouter le pecorino râpé en remuant vivement. Hors du feu, impérativement : sur la flamme, le fromage file en fils et la sauce graine.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-113', 'recipe_family', 'Amatriciana végétarienne',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-113', 'missing_required_count', v_missing), 'open');
  END IF;

