      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Spaghetti ou pâtes courtes à la place des bucatini, 320 g pour quatre (primochef, mammachechef, vegolosi)','Levure maltée en paillettes ou « parmesan végane » à la place du pecorino, pour une version végane — c''est ce que font les trois pages du dossier (primochef, mammachechef)','Une cuillerée à soupe de sauce soja avec le vin blanc, pour appuyer l''umami du tofu (mammachechef)','Passata rustique seule à la place des tomates pelées écrasées (vegolosi, primochef)','Sans oignon du tout, à la façon de l''amatriciana traditionnelle : le tofu est alors coloré directement dans l''huile']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-113","variants":["Spaghetti ou pâtes courtes à la place des bucatini, 320 g pour quatre (primochef, mammachechef, vegolosi)","Levure maltée en paillettes ou « parmesan végane » à la place du pecorino, pour une version végane — c''est ce que font les trois pages du dossier (primochef, mammachechef)","Une cuillerée à soupe de sauce soja avec le vin blanc, pour appuyer l''umami du tofu (mammachechef)","Passata rustique seule à la place des tomates pelées écrasées (vegolosi, primochef)","Sans oignon du tout, à la façon de l''amatriciana traditionnelle : le tofu est alors coloré directement dans l''huile"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-113', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('53ac4a3f577b75f126237fd9fd9aae49'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"tomato_herbal","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":1,"pungency":2,"richness":2,"freshness":2,"intensity":4},"dominant_flavors":["tomate","fumé","acidulé"],"aroma_families":["tomate_cuite","fumé","piment","pecorino"],"target_textures":["pâtes_fermes","sauce_brillante","dés de tofu croustillants"],"signature_ingredients":["Bucatini secs","Tofu fumé","Pecorino romano","Tomate entière pelée en conserve"],"identity_guardrails":["Le tofu se colore franchement avant la tomate : sans cette croûte il reste blanc et mou dans la sauce, et le plat perd ce que le guanciale lui donnait","Pas de crème : la sauce se lie à l''eau de cuisson des pâtes et à rien d''autre","L''oignon reste discret — 15 g par personne — et fondu sans coloration : dominant, ce n''est plus une amatriciana","Le pecorino s''ajoute hors du feu, sinon il file et la sauce graine","Le tofu est fumé et non nature : c''est le fumé qui tient le rôle du guanciale"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salmorejo aux œufs durs', 'salmorejo aux oeufs durs', 'Espagne', 'Espagne',
     'meal', 'soupe froide épaisse', 'named_traditional_dish', 'fresh_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salmorejo aux œufs durs', 'Le salmorejo cordouan de REAL-115 sans son jambon : la même crème froide de tomate, de pain et d''huile d''olive, garnie du seul œuf dur écrasé.', ds.id, 'JUM-114',
    'Myko', 'editorial', 6, 25, 10, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '668c681dffd67c67f736ed61091af7a8',
    '{"sweet":1,"salty":2,"acidic":5,"bitter":1,"umami":2,"heat":0,"pungency":2,"richness":1,"freshness":5,"intensity":3}'::jsonb, ARRAY['tomate crue','huile d''olive','acidulé']::text[],
    ARRAY['tomate','huile_olive','ail','vinaigre']::text[], ARRAY['très_épais_et_soyeux','œuf émietté distinct']::text[],
    ARRAY['Tomate fraîche mûre','Pain blanc rassis','Huile d''olive vierge extra','Œuf dur']::text[], ARRAY['Plus épais qu''un gaspacho : c''est le pain, et non l''eau, qui fait la texture','L''huile se verse en filet dans le mixeur en marche — versée d''un coup, elle ne s''émulsionne pas et le plat reste rouge et liquide','Ne pas sur-mixer après l''huile : elle vire à l''amertume et rien ne la rattrape','Se sert froid, jamais à température : une heure de réfrigérateur au minimum, et le plat gagne à attendre plus','L''œuf dur est ici la seule garniture — le jambon du plat d''origine est ce que ce jumeau retire, et rien ne le remplace']::text[],
    ARRAY['mondage','mixage','émulsion','refroidissement']::text[], ARRAY['Croûtons de mie frits à l''huile d''olive à la place du jambon, deux tranches de pain pour quatre parts (secretosdelsur)','Un œuf dur mixé dans la soupe elle-même, en plus de celui de la garniture, pour une crème encore plus dense (spanishsabores)','Tomates non mondées, quand le mixeur est assez puissant pour ne rien laisser passer (secretosdelsur, fussfreeflavours)','Sans vinaigre du tout, la crème ne tenant son acidité que de la tomate (directoalpaladar)','Poivre noir au moulin dans la soupe et sur l''assiette (themediterraneandish)','Version végane du dossier, qui est un autre plat : tofu ferme, avocat, amandes, noix et pistaches mixés avec la tomate, relevés de curry et de curcuma (turecetavegana)']::text[], ARRAY['gluten','œuf','sulfites']::text[],
    'Trois jours au réfrigérateur, en bocal ou en bouteille fermée. L''émulsion se sépare doucement au fil des heures : ce n''est pas un défaut, mais il faut redonner un tour de cuillère avant de servir. Le plat gagne d''ailleurs à être fait la veille. Sur le froid les pages s''accordent ; sur sa durée, moins qu''il n''y paraît : fussfreeflavours pose trente minutes au minimum et conseille « une paire d''heures », themediterraneandish demande une heure, secretosdelsur dit seulement « un moment au réfrigérateur ». On écrit donc UNE heure — le minimum le plus exigeant qu''une page pose — et non les deux qu''aucune ne réclame. Il ne se congèle pas : au dégel, l''huile se sépare franchement et la mie de pain ressort granuleuse, c''est-à-dire qu''on perdrait exactement les deux choses qui font le salmorejo. Aucune page ne l''écrit ; c''est la lecture d''une émulsion de pain et d''huile. Les œufs durs se cuisent le jour même.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-115'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
