DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tofu sauté aux poivrons', 'tofu saute aux poivrons', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'plat sauté', 'domestic_standard', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Tofu sauté aux poivrons', 'Le poulet aux poivrons de RAP-035 avec du tofu ferme à la place de la volaille : mêmes trois couleurs de poivron, même oignon, même ail et même gingembre, même feu vif.', ds.id, 'JUM-115',
    'Myko', 'editorial', 4, 20, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f8998881b1e1a1a41b34b478bfed4369',
    '{"sweet":3,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":1,"pungency":3,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['poivron','sauce soja','gingembre','oignon']::text[],
    ARRAY['végétal grillé','gingembre','allium','soja']::text[], ARRAY['poivrons croquants','cubes de tofu dorés','bords_grillés']::text[],
    ARRAY['Tofu ferme','Poivron rouge frais','Gingembre frais']::text[], ARRAY['Le tofu se presse vingt minutes avant tout : non pressé, il bout dans son eau et ne dore jamais','Feu vif du début à la fin : à feu doux les poivrons compotent et le plat change de nature','Le tofu est saisi puis réservé, il ne cuit pas avec les légumes','Trois couleurs de poivron, comme chez la base carnée','Ail et gingembre entrent en dernier, pour ne pas brûler','Pas de sauce liée à la fécule : le jus des légumes et la sauce soja suffisent, sans quoi ce n''est plus le sauté de RAP-035']::text[],
    ARRAY['pressage du tofu','saisie','sauté','cuisson courte']::text[], ARRAY['Tofu roulé dans la fécule de maïs avant la poêle, pour une croûte plus franche (littlespicejar, rainbowplantlife)','Tofu tranché fin, badigeonné de sauce et rôti au four à 220 °C, dix minutes par face, au lieu de la sauteuse (plantbasedrdblog)','Sauce montée en fin de cuisson : sirop d''érable ou sucre, hoisin ou vinaigre de riz (livinglou, plantbasedrdblog, createmindfully), liée d''une cuillerée de fécule délayée dans l''eau chez la seule plantbasedrdblog','Huile de sésame grillé dans la marinade et graines de sésame en finition (livinglou) — littlespicejar, à qui la première rédaction les attribuait aussi, n''en porte ni dans sa liste ni dans sa méthode','Carottes en julienne et champignons bruns ajoutés aux poivrons (createmindfully)','Piment frais — serrano, fresno — ou flocons de piment avec l''ail et le gingembre (livinglou, createmindfully, littlespicejar)','Échalotes émincées à la place de l''oignon (littlespicejar)','Tofu fumé et poivron vert seul, à la façon du wok français écarté du dossier (kintaki)']::text[], ARRAY['soja']::text[],
    'Deux jours au réfrigérateur, pas plus, et avec la même réserve que la version au poulet : les poivrons y perdent leur croquant, qui est tout l''intérêt du plat. Le réemploi le plus juste est froid, en salade ou dans un wrap, plutôt que réchauffé ; à la poêle très chaude et brièvement si l''on tient au chaud, jamais au micro-ondes. La congélation est possible 2 mois mais elle change le tofu plus qu''elle ne le conserve : l''eau qu''il porte gèle en cristaux qui percent sa trame et il ressort spongieux — certains cuisiniers congèlent d''ailleurs leur tofu exprès pour cela, mais ce n''est plus la texture de ce plat-ci.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'RAP-035'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
