  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Égoutter le tofu, l''envelopper dans un linge propre et le presser vingt minutes sous un poids — une casserole remplie d''eau fait l''affaire. Cette eau-là ne partira plus à la poêle : un tofu non pressé bout dans son propre jus et ne colore jamais, quelle que soit la chaleur qu''on lui donne.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Le tailler en cubes de deux centimètres. Fendre les poivrons, ôter les graines et surtout les cloisons blanches, qui portent l''amertume, puis les couper en lanières d''un centimètre. Trancher l''oignon en demi-lunes d''une épaisseur voisine : dans un sauté, ce qui entre ensemble doit cuire ensemble.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire chauffer la moitié de l''huile à feu vif dans une grande sauteuse et y ranger les cubes de tofu en une seule couche, sans qu''ils se touchent. Les laisser trois minutes sans y toucher, puis les retourner face après face, huit à dix minutes en tout, jusqu''à ce qu''ils soient dorés et fermes sous la spatule. Les réserver. Un tofu qu''on remue trop tôt s''accroche et se casse ; il se détache tout seul dès que la croûte est faite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser le reste de l''huile, jeter poivrons et oignon dans la sauteuse brûlante et les remuer sans arrêt huit à dix minutes, feu au maximum. On veut des arêtes marquées et un cœur encore croquant : à feu modéré, ils rendent leur eau, s''affaissent et deviennent une compotée, qui est un autre plat sous un autre nom.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Jeter l''ail haché et le gingembre râpé, remuer une minute, le temps que le parfum monte. Entrés au début, ils n''auraient pas tenu les dix minutes de feu vif que réclament les légumes et auraient viré à l''amer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre le tofu et le jus qu''il a rendu, verser la sauce soja et sauter une minute de plus en remuant, le temps qu''elle enrobe les cubes et réduise de moitié. Elle doit laquer et non napper : ce sauté ne porte aucune sauce montée, son liant est le jus des légumes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Donner un tour de moulin, goûter, et ne saler qu''ensuite, d''une pincée au plus : la sauce soja a déjà fait le travail. Servir sur du riz sans attendre. Ce plat ne tient pas au chaud — dix minutes de plus et le croquant des poivrons a disparu, c''est-à-dire la raison même de le cuisiner.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-115', 'recipe_family', 'Tofu sauté aux poivrons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-115', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Tofu roulé dans la fécule de maïs avant la poêle, pour une croûte plus franche (littlespicejar, rainbowplantlife)','Tofu tranché fin, badigeonné de sauce et rôti au four à 220 °C, dix minutes par face, au lieu de la sauteuse (plantbasedrdblog)','Sauce montée en fin de cuisson : sirop d''érable ou sucre, hoisin ou vinaigre de riz (livinglou, plantbasedrdblog, createmindfully), liée d''une cuillerée de fécule délayée dans l''eau chez la seule plantbasedrdblog','Huile de sésame grillé dans la marinade et graines de sésame en finition (livinglou) — littlespicejar, à qui la première rédaction les attribuait aussi, n''en porte ni dans sa liste ni dans sa méthode','Carottes en julienne et champignons bruns ajoutés aux poivrons (createmindfully)','Piment frais — serrano, fresno — ou flocons de piment avec l''ail et le gingembre (livinglou, createmindfully, littlespicejar)','Échalotes émincées à la place de l''oignon (littlespicejar)','Tofu fumé et poivron vert seul, à la façon du wok français écarté du dossier (kintaki)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-115","variants":["Tofu roulé dans la fécule de maïs avant la poêle, pour une croûte plus franche (littlespicejar, rainbowplantlife)","Tofu tranché fin, badigeonné de sauce et rôti au four à 220 °C, dix minutes par face, au lieu de la sauteuse (plantbasedrdblog)","Sauce montée en fin de cuisson : sirop d''érable ou sucre, hoisin ou vinaigre de riz (livinglou, plantbasedrdblog, createmindfully), liée d''une cuillerée de fécule délayée dans l''eau chez la seule plantbasedrdblog","Huile de sésame grillé dans la marinade et graines de sésame en finition (livinglou) — littlespicejar, à qui la première rédaction les attribuait aussi, n''en porte ni dans sa liste ni dans sa méthode","Carottes en julienne et champignons bruns ajoutés aux poivrons (createmindfully)","Piment frais — serrano, fresno — ou flocons de piment avec l''ail et le gingembre (livinglou, createmindfully, littlespicejar)","Échalotes émincées à la place de l''oignon (littlespicejar)","Tofu fumé et poivron vert seul, à la façon du wok français écarté du dossier (kintaki)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-115', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f8998881b1e1a1a41b34b478bfed4369'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":3,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":1,"pungency":3,"richness":2,"freshness":2,"intensity":3},"dominant_flavors":["poivron","sauce soja","gingembre","oignon"],"aroma_families":["végétal grillé","gingembre","allium","soja"],"target_textures":["poivrons croquants","cubes de tofu dorés","bords_grillés"],"signature_ingredients":["Tofu ferme","Poivron rouge frais","Gingembre frais"],"identity_guardrails":["Le tofu se presse vingt minutes avant tout : non pressé, il bout dans son eau et ne dore jamais","Feu vif du début à la fin : à feu doux les poivrons compotent et le plat change de nature","Le tofu est saisi puis réservé, il ne cuit pas avec les légumes","Trois couleurs de poivron, comme chez la base carnée","Ail et gingembre entrent en dernier, pour ne pas brûler","Pas de sauce liée à la fécule : le jus des légumes et la sauce soja suffisent, sans quoi ce n''est plus le sauté de RAP-035"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Soupe avgolemono végétarienne', 'soupe avgolemono vegetarienne', 'Grèce', 'Grèce',
     'meal', 'soupe complète', 'named_traditional_dish', 'tangy_creamy',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Soupe avgolemono végétarienne', 'L''avgolemono grec sans son poulet : bouillon de légumes, riz rond cuit jusqu''à l''amidon, pois chiches, et la même liaison d''œufs battus au jus de citron, montée hors du feu.', ds.id, 'JUM-121',
    'Myko', 'editorial', 6, 20, 30, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '767ec2bbb636adda8e3f9a8c69c9f62d',
    '{"sweet":1,"salty":3,"acidic":4,"bitter":0,"umami":2,"heat":1,"pungency":2,"richness":3,"freshness":3,"intensity":4}'::jsonb, ARRAY['acidulé','crémeux','aneth']::text[],
    ARRAY['citron','agrume','œuf','aneth','oignon_compoté','végétal cuit']::text[], ARRAY['bouillon_velouté','riz_moelleux','pois chiche fondant']::text[],
    ARRAY['Riz rond cru','Œuf cru','Jus de citron frais','Pois chiche cuit, égoutté']::text[], ARRAY['La liaison se monte hors du feu et la soupe ne rebout jamais : c''est tout le plat, et l''erreur est irréversible','L''œuf est battu avec le jus de citron avant d''être tempéré, jamais versé seul dans le bouillon','Pas de crème : l''onctuosité vient de l''œuf et de l''amidon du riz, pas d''un produit laitier','Le bouillon est de légumes, jamais de volaille — c''est ce qui sépare ce jumeau de sa base carnée','Le riz cuit dans le bouillon lui-même et jusqu''à s''écraser : un riz al dente ne libère pas l''amidon qui protège la liaison']::text[],
    ARRAY['suer','cuisson du riz','tempérage','liaison aux œufs','assaisonnement tardif']::text[], ARRAY['Riz long à la place du riz rond, majoritaire dans le dossier (sweetrecipeas, thefullhelping) — la soupe est moins liée et les grains restent détachés','Orzo à la place du riz, 1 tasse pour huit à dix parts (gimmesomeoven, thefullhelping en repli)','Deux feuilles de laurier dans le bouillon et une demi-tasse d''oignon nouveau dans la base aromatique (liveeatlearn)','Deux poignées de pousses d''épinard fondues dans la soupe juste avant de servir (gimmesomeoven)','Version vegan sans œuf, la liaison étant faite d''une crème de noix de cajou mixée au bouillon, ou d''un mélange miso-tahini-levure maltée (connoisseurusveg, thefullhelping, foodbymaria) — ce n''est plus un avgolemono au sens du parent','Lanières de faux poulet effilochées ajoutées à la fin, pour rapprocher la soupe de sa version carnée (sweetrecipeas)','Persil plat à la place de l''aneth (foodbymaria)']::text[], ARRAY['œuf','céleri']::text[],
    'Se garde 2 jours au réfrigérateur en récipient fermé et se réchauffe à feu doux, sans jamais atteindre l''ébullition : passé 85 °C la liaison à l''œuf tranche et la soupe devient granuleuse. Aucune des six pages du dossier ne dit un mot de conservation — ce qui suit est donc ce que ce type de plat fait physiquement, et on l''annonce comme tel plutôt que de le prêter aux sources. La congélation est déconseillée, pour deux raisons qui s''ajoutent : l''œuf coagulé se sépare de son bouillon à la décongélation et donne une soupe caillée, et le riz, qui a déjà rendu tout son amidon, se délite en bouillie. Pour prendre de l''avance, s''arrêter à la fin de l''étape 3 : cette base de bouillon, riz et pois chiches se garde 3 jours au réfrigérateur ou 2 mois à -18 °C, et la liaison œuf-citron se monte à la minute, sur la soupe réchauffée puis retirée du feu.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-129'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'bouillon de legumes non sale' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Bouillon de légumes non salé', 1800, 'ml', 'required',
     'cuisson', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'riz rond cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Riz rond cru', 180, 'g', 'required',
     'féculent', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pois chiche cuit egoutte' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
