  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler la carotte, le céleri et l''oignon en dés d''un demi-centimètre, hacher l''ail. Chauffer l''huile d''olive dans un faitout et y faire fondre les trois légumes à feu moyen sept à huit minutes, en remuant, jusqu''à ce qu''ils s''assouplissent sans prendre la moindre couleur ; ajouter l''ail pour une minute de plus. Chez la version au poulet, ces mêmes légumes pochaient avec la volaille et finissaient au filtre : ils parfumaient un jus qu''on jetait. Ici rien ne sera filtré, ils restent dans l''assiette, et une coloration leur donnerait un fond grillé qui se battrait avec le citron.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Verser le bouillon de légumes, poivrer, saler à moitié seulement, porter à frémissement puis jeter le riz en pluie. Cuire vingt minutes à couvert et à tout petit feu, jusqu''à ce qu''un grain s''écrase sans résistance entre deux doigts. On dépasse volontairement le point d''un riz d''accompagnement : c''est l''amidon relâché qui épaissira le bouillon et, surtout, qui protégera l''œuf de la coagulation au moment de la liaison.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Rincer les pois chiches à l''eau froide et les égoutter, puis les verser dans le faitout cinq minutes avant la fin de la cuisson du riz, le temps de les réchauffer seulement. Le rinçage emporte la saumure de la conserve, qui salerait la soupe avant qu''on ait pu la goûter ; entrés plus tôt, les grains se déferaient et troubleraient un bouillon qui doit rester lisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant ce temps, casser les œufs dans un grand saladier et les battre au fouet avec le jus de citron, une minute pleine, jusqu''à ce que le mélange mousse et pâlisse. L''acide commence à dénaturer le blanc à froid, et c''est ce début de travail qui permettra ensuite à l''œuf d''encaisser la chaleur sans se prendre en filaments.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Tempérer. Prélever une louche de bouillon brûlant et la verser sur les œufs battus en filet aussi mince que possible, sans jamais cesser de fouetter, puis recommencer avec une deuxième louche : le saladier doit devenir tiède au toucher. C''est l''étape entière du plat. Un œuf versé d''un coup dans une casserole chaude donne une soupe grumeleuse, et rien ne la rattrape — ni le mixeur, ni le tamis, qui retireraient la liaison en même temps que les grumeaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Retirer le faitout du feu et attendre une minute que le frémissement cesse tout à fait, puis reverser la liaison en tournant lentement. Ne plus jamais faire bouillir : passé 85 °C l''œuf coagule et le velouté tombe d''un coup. Ajouter l''aneth ciselé hors du feu pour qu''il garde son parfum, rectifier le sel, le poivre et le citron, et servir tout de suite dans des assiettes creuses.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-121', 'recipe_family', 'Soupe avgolemono végétarienne',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-121', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Riz long à la place du riz rond, majoritaire dans le dossier (sweetrecipeas, thefullhelping) — la soupe est moins liée et les grains restent détachés','Orzo à la place du riz, 1 tasse pour huit à dix parts (gimmesomeoven, thefullhelping en repli)','Deux feuilles de laurier dans le bouillon et une demi-tasse d''oignon nouveau dans la base aromatique (liveeatlearn)','Deux poignées de pousses d''épinard fondues dans la soupe juste avant de servir (gimmesomeoven)','Version vegan sans œuf, la liaison étant faite d''une crème de noix de cajou mixée au bouillon, ou d''un mélange miso-tahini-levure maltée (connoisseurusveg, thefullhelping, foodbymaria) — ce n''est plus un avgolemono au sens du parent','Lanières de faux poulet effilochées ajoutées à la fin, pour rapprocher la soupe de sa version carnée (sweetrecipeas)','Persil plat à la place de l''aneth (foodbymaria)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-121","variants":["Riz long à la place du riz rond, majoritaire dans le dossier (sweetrecipeas, thefullhelping) — la soupe est moins liée et les grains restent détachés","Orzo à la place du riz, 1 tasse pour huit à dix parts (gimmesomeoven, thefullhelping en repli)","Deux feuilles de laurier dans le bouillon et une demi-tasse d''oignon nouveau dans la base aromatique (liveeatlearn)","Deux poignées de pousses d''épinard fondues dans la soupe juste avant de servir (gimmesomeoven)","Version vegan sans œuf, la liaison étant faite d''une crème de noix de cajou mixée au bouillon, ou d''un mélange miso-tahini-levure maltée (connoisseurusveg, thefullhelping, foodbymaria) — ce n''est plus un avgolemono au sens du parent","Lanières de faux poulet effilochées ajoutées à la fin, pour rapprocher la soupe de sa version carnée (sweetrecipeas)","Persil plat à la place de l''aneth (foodbymaria)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-121', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('767ec2bbb636adda8e3f9a8c69c9f62d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"tangy_creamy","scores":{"sweet":1,"salty":3,"acidic":4,"bitter":0,"umami":2,"heat":1,"pungency":2,"richness":3,"freshness":3,"intensity":4},"dominant_flavors":["acidulé","crémeux","aneth"],"aroma_families":["citron","agrume","œuf","aneth","oignon_compoté","végétal cuit"],"target_textures":["bouillon_velouté","riz_moelleux","pois chiche fondant"],"signature_ingredients":["Riz rond cru","Œuf cru","Jus de citron frais","Pois chiche cuit, égoutté"],"identity_guardrails":["La liaison se monte hors du feu et la soupe ne rebout jamais : c''est tout le plat, et l''erreur est irréversible","L''œuf est battu avec le jus de citron avant d''être tempéré, jamais versé seul dans le bouillon","Pas de crème : l''onctuosité vient de l''œuf et de l''amidon du riz, pas d''un produit laitier","Le bouillon est de légumes, jamais de volaille — c''est ce qui sépare ce jumeau de sa base carnée","Le riz cuit dans le bouillon lui-même et jusqu''à s''écraser : un riz al dente ne libère pas l''amidon qui protège la liaison"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Croque-madame aux épinards', 'croque madame aux epinards', 'France', 'France',
     'meal', 'sandwich chaud', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Croque-madame aux épinards', 'Le croque-madame sans jambon : des pousses d''épinard tombées à la poêle et pressées remplacent la tranche de charcuterie, entre deux couches d''emmental, sous le gruyère gratiné et l''œuf au plat.', ds.id, 'JUM-122',
    'Myko', 'editorial', 4, 15, 12, 'facile',
    NULL, NULL,
    'B', 'candidate', '439b98866432d56a0a298a5a6d7bcc32',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3}'::jsonb, ARRAY['fromage fondu','épinard','beurre doré']::text[],
    ARRAY['lactée','grillée','beurre','végétal cuit']::text[], ARRAY['pain grillé croustillant','fromage fondant','jaune d''œuf coulant']::text[],
    ARRAY['Pain de mie','Œuf cru','Épinard frais','Emmental râpé']::text[], ARRAY['Sans l''œuf au plat posé sur le dessus, le plat redevient un croque-monsieur et perd son nom','Le pain de mie est la seule enveloppe admise : sur une baguette ou un pain de campagne, ce n''est plus un croque','Les épinards sont tombés puis pressés avant le montage — non pressés, ils détrempent la mie et le croque s''affaisse','L''épinard est pris entre deux couches de fromage, jamais posé à même le pain','Aucune charcuterie : c''est l''épinard qui tient la place du jambon, et c''est ce qui fait de cette fiche le jumeau de sa base']::text[],
    ARRAY['saisie','gratinage','montage','égouttage']::text[], ARRAY['Épinards en branches surgelés déjà à la crème, 160 g par part, à la place des pousses fraîches tombées à la poêle (chefsimon)','Une couche de béchamel tartinée sur la face intérieure du pain, 20 g par croque (cuisine-facile)','Tomates compotées avec un oignon nouveau à la place des épinards, 500 à 600 g pour quatre, liées d''une crème au parmesan (recettesetcabas)','Champignons de Paris poêlés avec les épinards, 100 g pour quatre (blog.pourdebon)','Tomme des Bauges en tranches à la place de l''emmental râpé (blog.pourdebon), ou fromage à pâte molle en lamelles fines (cuisine-facile)','Pain de mie complet ou aux céréales plutôt que blanc, proposé par trois pages (chefsimon, recettesetcabas, cuisine-facile)','Une pointe d''échalote en poudre et de piment d''Espelette dans la garniture (chefsimon)','Œufs de caille, trois par croque, à la place de l''œuf de poule (lesfruitsetlegumesfrais)']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se mange dans la minute : le jaune coulant ne supporte pas l''attente et la croûte ramollit en quelques minutes. Un croque monté et déjà garni se garde au maximum 24 heures à 4 °C et se réchauffe dix minutes à 180 °C, l''œuf devenant alors ferme — c''est la durée que porte la fiche parente et aucune page du dossier ne la contredit ni ne la confirme, aucune ne parlant de conservation. La congélation ne convient qu''au croque monté CRU et non coiffé de son œuf, jusqu''à 1 mois à -18 °C, à cuire sans décongélation préalable en comptant deux minutes de plus par face. Une précision propre à cette version, et qui vient de la physique du légume plutôt que des sources : les épinards doivent avoir été tombés et pressés AVANT congélation, sinon l''eau qu''ils gardent gèle en cristaux et ressort dans la mie à la cuisson.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-011'), '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pain de mie' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pain de mie', 240, 'g', 'required',
     'base féculente', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oeuf cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Œuf cru', 200, 'g', 'required',
     'protéine', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'epinard frais' AND ff.status <> 'rejected'
